(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-pd-disagg-rollout"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-1\">一 · 一个把 TTFT 打穿的事故：混部池里 decode 与 prefill 互相踩踏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-2\">二 · 它解决的具体问题：按阶段拆池、按各自瓶颈独立扩缩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-3\">三 · 它不解决的问题：KV 复用、同池互补、单机小规模</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-4\">四 · 适用判据：用配比与传输项做一次算术</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-5\">五 · 失败模式与它的机制根源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-6\">六 · 拆池之后，故障从算力转移到互联</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-7\">七 · 请求入池：prefill 侧的组批与前向切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-8\">八 · KV 出池：按层分片的跨池写入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-9\">九 · decode 侧接管：纯 decode 批次的连续自回归</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-10\">十 · 两池各自的队列与扩缩容信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-11\">十一 · 权重同步：版本号原子切换的时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-12\">十二 · 端到端时序与 goodput 口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-13\">十三 · 拆池之后的失效边界：KV 搬运、版本错配与小集群的反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-14\">十四 · Goodput 与容量配比：两个公式的分母不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-15\">十五 · TTFT 分解：传输项是分离式独有的加项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-16\">十六 · 两池独立组批的伪代码骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-17\">十七 · 权重版本切换的原子性推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-18\">十八 · 传输量与显存总占用的联合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-19\">十九 · 与相邻算法的公式级分野</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-20\">二十 · 跨池传输项如何吃掉 TTFT 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-21\">二十一 · 什么请求形态才配得上拆池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-22\">二十二 · 长度分布决定配比，而不是平均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-23\">二十三 · 批大小两池独立，但独立不等于随意</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-24\">二十四 · 并发水位与两池队列的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-25\">二十五 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-26\">二十六 · 配方落地：从分布到配比到扩缩容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-27\">二十七 · 负载配方与失效边界：什么时候这套拆池方案会反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-28\">二十八 · 硬件档位：两池不同代际、不同形态的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-29\">二十九 · 并行拓扑：两池各自独立成型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-30\">三十 · 量化方案：按阶段分配精度预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-31\">三十一 · KV 策略：分片、流水重叠与容量水位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-32\">三十二 · 调度参数：两套 SLO 队列与权重版本闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-33\">三十三 · 可复现的配置思路：从长度分布反解配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-34\">三十四 · 分离式 Rollout 的失效边界与配比校准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-35\">三十五 · 互联带宽成为TTFT的第一约束项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-36\">三十六 · 显存总占用：两池副本与KV双写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-37\">三十七 · 通信拓扑与组批的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-38\">三十八 · 功耗与两池档位错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-39\">三十九 · 尾延迟：goodput口径下的真实损失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-40\">四十 · 权重切换窗口与版本错配的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-41\">四十一 · 跨池传输项：规模上去以后最先崩的是互联带宽，不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-42\">四十二 · 精度漂移：版本错配与数值路径分叉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-43\">四十三 · OOM：两池副本与 KV 峰值叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-44\">四十四 · 批抖动与路由不均：两个不同源的尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-45\">四十五 · 监控口径：以 SLO 为唯一裁决</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-46\">四十六 · 回滚：分级动作与原子边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-47\">四十七 · 失效边界：跨池带宽、版本错配与副本开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-48\">四十八 · 同族算法的三条分界线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-49\">四十九 · 决策表：五种形态的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-50\">五十 · 用 TTFT 分解式做定量筛选</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-51\">五十一 · 权重同步与版本一致性作为选型硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-52\">五十二 · 规模门槛与显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-pd-disagg-rollout-sec-53\">五十三 · 分池边界：什么规模的 rollout 才值得拆</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:512px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout请求先进入prefill池，按chunk组批完成全promp…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV按层分片经NVLink/CXL/IB写入decode池对应block …</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">decode池以纯decode批次连续自回归，直到EOS或长度上限</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">两池各自维护队列与SLO，prefill池按TTFT目标扩容，decode…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"430.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">训练侧新权重通过权重同步通道分别推送到两池，按版本号原子切换</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-pd-disagg-rollout-sec-1\">一 · 一个把 TTFT 打穿的事故：混部池里 decode 与 prefill 互相踩踏</h3>\n<p>某 RL 训练任务的 rollout 引擎跑在单一 GPU 池上：同一批 GPU 既做预填也做解码，调度器把新到的长 prompt 请求和正在自回归的序列拼进同一个批次。事故是这样发生的：训练侧刚推送一版新权重，rollout 侧需要立刻换权重以保持样本与策略一致；换权重意味着整个池要排空在飞请求，而池里恰好积压了一批输出长度很长的序列，它们已经连续解码了数千步。排空窗口被这些长序列拖长，新到的 rollout 请求在队列里等待，TTFT 迅速越过 SLO 阈值。更糟的是，为了不让 GPU 空转，调度器把新请求的 prefill 强行插进正在解码的批次，prefill 的大矩阵乘瞬间把 decode 的 TPOT 顶上去，已经接近 EOS 的序列被迫拉长，反过来又延长了排空窗口。这是一次典型的正反馈式拥塞：prefill 拖慢 decode，decode 拖慢换权重，换权重拖慢 prefill。</p>\n<p>这个事故的根因不是某个 kernel 写得不好，而是两个阶段的资源画像根本相反。prefill 是计算密集型，一次前向要吞下整段 prompt，吃的是 tensor core 的算力与 HBM 带宽；decode 是访存密集型，每步只处理一个 token，却要把整个 KV cache 与权重读一遍，吃的是 HBM 容量与带宽。混部时，两者的瓶颈无法同时被喂饱：给 prefill 加大批，decode 的步间延迟抖动；给 decode 保实时，prefill 的算力利用率塌下来。用 SLO 口径衡量，混部池的 goodput 被两类违约同时侵蚀：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}]}{T},\\quad C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>第二个式子给出的是两阶段算力需求的配比：它由请求到达率、平均 prompt 长度与平均输出长度共同决定。RL rollout 的负载配方恰恰是长 prompt、长输出混合，这个配比在训练过程中还会随策略演化漂移。混部池的物理配比是固定的，于是任何一次分布漂移都会让一侧成为瓶颈，另一侧闲置。事故里的“排空窗口”只是把这个结构性矛盾暴露在了权重切换这一个时间点上。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-2\">二 · 它解决的具体问题：按阶段拆池、按各自瓶颈独立扩缩容</h3>\n<p>预填解码分离 Rollout 的做法是把数据流切成两段，分别落在不同的 GPU 池上。rollout 请求先进入 prefill 池，按 chunk 组批完成全 prompt 前向，产出首 token 与完整 KV；KV 按层分片，经 NVLink、CXL 或 IB 写入 decode 池对应的 block table，传输与计算流水重叠；decode 池以纯 decode 批次连续自回归，直到 EOS 或长度上限。两池各自维护队列与 SLO：prefill 池按 TTFT 目标扩容，decode 池按 TPOT 目标扩容。训练侧新权重通过权重同步通道分别推送到两池，按版本号原子切换。</p>\n<p>它解决的问题可以精确地写成三条。第一，消除阶段间的批内干扰：prefill 池的批次里只有 prefill，decode 池的批次里只有 decode，长 prompt 不再打断正在解码的序列，decode 的步间延迟由纯 decode 批的规模决定，可预测性大幅提升。第二，让资源配比成为可调参数：两池的 GPU 档位、并行拓扑、批大小独立设定，运维可以按当前 rollout 的 prompt/输出长度分布调整 $C_{\\text{pre}}/C_{\\text{dec}}$，而不是被一台机器的固定切分绑死。第三，把训练-推理解耦做彻底：权重同步通道独立于请求数据通路，换权重不再需要排空整个混部池，两池可以按版本号原子生效，事故里那种“排空窗口被长序列拖长”的链条被切断。</p>\n<p>代价同样具体。KV 跨池传输要占互联带宽，并直接加到 TTFT 上：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>其中 $S_{\\text{KV}}$ 是单请求 KV 字节数，$BW_{\\text{interconnect}}$ 是跨池互联带宽。长 prompt、大模型时，单请求 KV 传输量可达数百 MB，这一项不再是噪声。此外两池各持独立副本与调度器，显存总占用与部署复杂度都上升。这不是免费的架构，它用互联带宽和显存换阶段隔离与弹性。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-3\">三 · 它不解决的问题：KV 复用、同池互补、单机小规模</h3>\n<p>边界的第一条是 KV 复用。分离式拆池按阶段切开数据流，但同一 prompt 前缀在多次 rollout 之间的 KV 复用不在它的机制范围内——那是 KV 中心分离式池化以 KV 为一级调度对象做的事，本算法只保证 KV 从 prefill 池正确搬到 decode 池，不负责跨请求的全局复用。第二条是同池内的瓶颈互补。分块预填背驮解码在同池内把 prefill 与 decode 拼批，用计算密集段填访存密集段的空档；分离式拆池走的是相反方向，用物理隔离代替批内互补，两者适用规模不同，不能互相替代。第三条是单机或小规模集群。两池独立副本使显存总占用上升，小规模下资源利用率反而下降，部署复杂度也不划算——当集群规模不足以让两池都跑到有意义的批大小时，拆池的收益被副本开销吃掉。</p>\n<p>还有一条隐含边界：它不改变单请求的算法复杂度，也不解决数值精度问题。NVFP4/FP8 量化带来的稳定性问题、批不变采样的一致性，都需要各自的机制处理；分离式拆池只负责把阶段资源解耦，量化档位与采样策略不在它的决策面上。规模上限则受两个物理量约束：跨池互联带宽决定 $S_{\\text{KV}}/BW_{\\text{interconnect}}$ 能否被流水重叠隐藏，两池副本显存决定 decode 池能容纳多少并发序列。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-4\">四 · 适用判据：用配比与传输项做一次算术</h3>\n<p>判断一个 rollout 负载是否该拆池，可以先算两件事。第一件是阶段配比 $C_{\\text{pre}}/C_{\\text{dec}}$ 是否显著偏离 1：若 prompt 长度与输出长度之比让 prefill 算力需求远大于或远小于 decode，混部池必然一侧闲置，拆池的弹性收益就成立。第二件是传输项占 TTFT 的比例：若 $S_{\\text{KV}}/BW_{\\text{interconnect}}$ 相对 $T_{\\text{prefill}}$ 可以忽略，或能被传输与计算流水重叠完全隐藏，拆池的延迟代价就小；反之，长 prompt、大模型使单请求 KV 达数百 MB 时，互联带宽就是硬约束，拆池前必须先确认互联余量。</p>\n<p>一个具体的工程判断：当 rollout 请求形态是长 prompt、长输出混合，且集群规模足以让 prefill 池与 decode 池各自维持有意义的批大小时，拆池是正确选择；当负载以短 prompt、短输出为主，阶段配比接近 1，或集群规模小到两池副本开销超过隔离收益时，应留在同池方案，用分块预填背驮解码之类的批内互补手段处理干扰。事故里那个混部池的真正错误不在于选了混部，而在于负载配方已经漂移到长 prompt、长输出，却仍用固定配比的单池承载，且权重切换没有独立通道——这两点正是分离式拆池直接针对的。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-5\">五 · 失败模式与它的机制根源</h3>\n<p>拆池之后，事故不会消失，只会换形态。第一种失败模式是 KV 跨池传输占满互联带宽，长 prompt 场景 TTFT 超出 SLO：传输项 $S_{\\text{KV}}/BW_{\\text{interconnect}}$ 在互联被其他流量挤占时不再是可隐藏的小量，prefill 池算得再快，首 token 也卡在搬运上。第二种是两池权重版本切换不同步，decode 池用旧权重产出与训练侧不一致的样本：权重同步通道若没有按版本号原子切换，prefill 池已切到新版本而 decode 池还在旧版本，产出的 rollout 样本对训练侧就是脏数据，这类错误不会报错，只会以策略不一致的形式污染训练。第三种是小规模集群下两池独立副本使显存总占用翻倍，资源利用率反而下降——拆池的固定开销在规模不足时无法摊薄。</p>\n<p>这三种失败模式都指向同一个工程约束：拆池把耦合从批内转移到了互联与版本管理上。传输与计算流水重叠是隐藏第一种失败的机制，版本号原子切换是防止第二种失败的机制，而第三种只能靠规模判据提前排除。换句话说，这个算法的稳定性不取决于拆得干不干净，而取决于拆开之后那两条新通路——KV 传输通路与权重同步通路——是否被当作一等公民来设计。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-6\">六 · 拆池之后，故障从算力转移到互联</h3>\n<p>把 prefill 与 decode 拆到两个 GPU 池，最先暴露的不是算力不足，而是互联带宽成为新的单点。以一个线上 RL rollout 集群为例：训练侧每若干步就推送一版新权重，rollout 引擎必须尽快用新策略采样，否则样本与当前策略的偏差会污染优势估计。混部时，长 prompt 的 chunk 前向与 decode 的自回归批次挤在同一批 SM 上，prefill 的算力密集与 decode 的带宽密集互相踩踏，decode 的 TPOT 被长 prompt 打断，prefill 的 TTFT 又被 decode 的常驻批次拖长，goodput 按 SLO 口径塌陷。拆池的直接动机是把两种相反的瓶颈分开组批，但代价立刻显形：首 token 的时延不再只由 prefill 计算决定，而由</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>决定。当 prompt 很长、模型很大时，单请求 KV 字节数可达数百 MB，传输项随之前置放大；一旦互联被占满，prefill 池算得再快，decode 池也拿不到 KV，TTFT 直接越过 SLO。这不是容量问题，而是拓扑问题——拆池把原本在片内 HBM 完成的 KV 交接，变成了跨池的显式数据搬运。</p>\n<p>边界由此清晰。该方案适合大规模集群、且 rollout 的 prompt 与输出长度分布使两阶段资源需求差异明显的情形：prefill 池按 TTFT 目标扩容，decode 池按 TPOT 目标扩容，资源配比可按 \\(\\rho_{\\text{pre}}/\\rho_{\\text{dec}}\\) 与平均长度独立调优，训练与推理的解耦也更彻底。它不解决单请求内部的算力瓶颈，也不解决 KV 容量本身——decode 池仍要为每条在途序列持有完整 KV，两池各持独立副本与调度器，显存总占用上升。小规模集群下，两池副本使显存翻倍而请求量不足以摊薄，利用率反而下降，这是明确的不适用区。</p>\n<p>失效条件有三类，工程上必须分别设防。其一是传输占满互联：长 prompt 场景下 KV 搬运与计算若未流水重叠，TTFT 超出 SLO，需按层分片写入 decode 池的 block table 并与前向计算重叠，把搬运延迟藏进计算窗口。其二是权重版本错配：训练侧新权重经同步通道分别推送两池，若 decode 池仍用旧权重自回归，产出的样本与训练侧策略不一致，必须以版本号原子切换，任一侧未就绪即拒绝新请求进入。其三是小集群的资源反噬，两池独立扩缩容的调度开销与副本显存超过收益。判断是否拆池，先看单请求 KV 字节数与互联带宽之比是否落在 TTFT 预算之内，再看集群规模能否让两池各自跑到高利用率；两者任一不满足，同池内拼批互补瓶颈的分块预填方案仍是更稳的选择。</p>\n<h3 id=\"alg-pd-disagg-rollout-sec-7\">七 · 请求入池：prefill 侧的组批与前向切分</h3>\n<p>rollout 请求进入 prefill 池时，调度器拿到的输入是 prompt token 序列、采样参数、目标 SLO（TTFT 上限）以及当前训练侧权重版本号。输出有两个：首 token 的 logits（用于采样出第一个 decode token）和该请求的完整 KV。这一步的关键不是“把 prompt 跑完”，而是“按 chunk 组批，让不同长度的 prompt 在同一批次里被切成可对齐的片段”。</p>\n<p>具体机制上，prefill 池的调度器对队列中的请求做长度分桶，把长 prompt 切成固定 token 数的 chunk，短 prompt 直接整条入批；每个 chunk 走一次全 prompt 前向的片段，chunk 之间共享该请求已产出的 KV 前缀。组批时以 chunk 为粒度而非以请求为粒度，批次内各 chunk 的 token 数之和构成该步的计算量，注意力掩码按 chunk 边界对齐。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{batch}_t = \\{\\text{chunk}_{i,k} : \\sum_i |\\text{chunk}_{i,k}| \\le B_{\\text{pre}}\\},\\quad \\text{KV}_i \\mathrel{+}= \\text{Attn}(\\text{chunk}_{i,k}, \\text{KV}_i^{&lt;k})$$</div>\n<p>代价落在两处。计算侧，prefill 是算力密集的 GEMM 主导，chunk 切分让批次内 token 数可控，但 chunk 边界带来额外的 KV 读写——每个 chunk 都要把已累积的 KV 重新读入注意力，chunk 越细，KV 带宽开销越大。显存侧，prefill 池必须为在途请求保留完整 KV 直到传输完成，长 prompt 的 KV 占用在池内是峰值约束。举例：一条长 prompt 请求被切成若干 chunk 逐步前向，每个 chunk 完成后其 KV 增量即可按层分片发出，不必等整条 prompt 结束——这正是下一节流水重叠的前提。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-8\">八 · KV 出池：按层分片的跨池写入</h3>\n<p>prefill 池产出 KV 后，输入是 KV 张量（按层、按 head、按 token 位置组织）与 decode 池为该请求预分配的 block table 句柄；输出是 decode 池显存中已落位、可被注意力直接索引的 KV block。机制是“按层分片 + 流水重叠”：KV 不整块搬运，而是每层（或每几层）产出一片就立即经 NVLink/CXL/IB 写入 decode 池对应 block table 的物理页，传输与后续层的计算重叠。</p>\n<p>这一步的代价由传输量直接决定。单请求 KV 字节数为：</p>\n<div class=\"formula\">$$S_{\\text{KV}} = 2 \\cdot L_{\\text{layer}} \\cdot H_{\\text{kv}} \\cdot d_{\\text{head}} \\cdot L_{\\text{prompt}} \\cdot b_{\\text{elem}}$$</div>\n<p>其中系数 2 对应 K 与 V，$b_{\\text{elem}}$ 是每元素字节数（精度档位决定）。长 prompt、大模型时该值可达数百 MB/请求，这是本算法最硬的一项成本。它直接进入 TTFT：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>流水重叠的作用是把 $\\frac{S_{\\text{KV}}}{BW}$ 中能与计算并行的部分藏掉——首层 KV 在首层计算后即发出，末层 KV 发出时前面若干层的传输已完成，因此有效传输项接近“最后一层的传输尾延迟”而非全量串行。但重叠只藏得住与计算同量级的部分：当互联带宽被多条在途请求同时占满时，传输项重新暴露，长 prompt 场景下 TTFT 超出 SLO 就是这条路径的典型失败模式。工程判断是：prefill 池的并发在途请求数必须与互联带宽挂钩做准入控制，而不是只按算力扩容。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-9\">九 · decode 侧接管：纯 decode 批次的连续自回归</h3>\n<p>decode 池收到 KV 落位信号后，输入是该请求的 block table 句柄、首 token、采样参数与 TPOT 上限；输出是逐 token 的自回归序列，直到 EOS 或长度上限。机制核心是“纯 decode 批次”：decode 池的批次里只有 decode 步，不掺任何 prefill chunk，因此每步的计算形态固定为“单 token 的注意力 + FFN”，批次内各序列的 KV 长度可以不同但步进一致。</p>\n<p>连续批处理在此处的具体形态是：某序列到达 EOS 后立即从批次中摘除，其 block 归还池；新完成 KV 传输的请求在同一调度周期补位。批次大小的上界由 TPOT 目标反推——每步耗时近似正比于批次内序列数与平均 KV 长度，调度器按 TPOT 预算决定本步能容纳多少序列。代价是显存带宽：decode 是带宽密集阶段，每步都要把批次内所有序列的 KV 从显存读一遍，KV 越长、批次越大，单步带宽压力越高。举例：一条长输出请求在 decode 池里连续自回归，其 KV 随输出增长而增长，block table 按需追加物理页，若显存池碎片化严重，追加失败会触发抢占或重算，直接体现为 TPOT 抖动。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-10\">十 · 两池各自的队列与扩缩容信号</h3>\n<p>两池不共享调度器，各自维护队列与 SLO 计数器。prefill 池的扩容信号是队列中请求的预测 TTFT 超过 $S_{\\text{ttft}}$ 的比例；decode 池的扩容信号是滑动窗口内 TPOT 超过 $S_{\\text{tpot}}$ 的比例。这两个信号彼此独立，正是“按阶段弹性伸缩”的落点：prompt 变长时只扩 prefill 池，输出变长时只扩 decode 池。</p>\n<p>资源配比的定量依据是两阶段计算量之比：</p>\n<div class=\"formula\">$$\\frac{C_{\\text{pre}}}{C_{\\text{dec}}} = \\frac{\\rho_{\\text{pre}} \\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}} \\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>其中 $\\rho$ 为两池各自的到达率。rollout 的负载配方是长 prompt、长输出混合，$\\bar{L}_{\\text{prompt}}$ 与 $\\bar{L}_{\\text{out}}$ 的分布决定了这个比值，也就决定了 GPU 档位配比。代价在于：两池各持独立副本与调度器，显存总占用上升；小规模集群下副本开销摊不薄，利用率反而下降，这是适用边界里“不划算”的来源。工程上判断是否拆池，看的是 $\\bar{L}_{\\text{prompt}}/\\bar{L}_{\\text{out}}$ 的离散度是否大到混部组批无法同时满足两个 SLO，而不是看集群绝对规模。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-11\">十一 · 权重同步：版本号原子切换的时序</h3>\n<p>训练侧产出新权重后，输入是新版本权重分片与版本号；输出是两池各自完成加载并对外声明“当前服务版本 = v”。机制是权重同步通道分别向两池推送，各池内部按版本号原子切换：新版本加载到独立缓冲区，加载完成后一次性把调度器的版本指针指向新缓冲区，在途请求继续用旧版本跑完，新到请求用新版本。原子性保证的是“同一请求不会跨版本”，而不是“两池同时切换”。</p>\n<p>代价是切换窗口内的有效吞吐下降：加载新权重占用显存与互联带宽，prefill 池的 KV 传输与权重推送争抢同一互联资源，切换期间 TTFT 抬升。更严重的失败模式是两池版本错配——若 decode 池仍用旧权重而 prefill 池已切新权重，同一请求的 KV 由新权重算出、decode 由旧权重续写，产出的样本与训练侧策略不一致，这种样本进入训练会污染梯度。因此版本号必须随请求一路携带，decode 池在接管时校验版本号，不匹配则拒绝或重路由。工程判断是：权重切换应作为独立的运维事件与 rollout 流量错峰，切换窗口内主动收紧两池的准入，而不是让切换与满负荷流量并行。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-12\">十二 · 端到端时序与 goodput 口径</h3>\n<p>把五步串起来看，单请求的端到端时序是：入 prefill 队列等待 → chunk 组批前向（含 KV 增量传输重叠）→ 末层 KV 传输尾延迟 → decode 池接管 → 连续自回归至 EOS。每一步的代价归属清晰：等待与 chunk 前向记在 $T_{\\text{prefill}}$，KV 尾传输记在 $\\frac{S_{\\text{KV}}}{BW}$，decode 步进记在 TPOT。goodput 按 SLO 口径统计：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i \\le S_{\\text{ttft}} \\wedge \\text{TPOT}_i \\le S_{\\text{tpot}}]}{T}$$</div>\n<p>这个口径下，拆池的收益不是“平均延迟变低”，而是“同时满足两个约束的请求比例变高”——混部时 prefill 被 decode 拖慢、decode 被长 prompt 打断，两类违约同时发生；拆池后两类违约各自被独立控制。举例：一批长 prompt 请求集中到达时，prefill 池按 TTFT 扩容吸收突发，decode 池的 TPOT 不受影响；反之输出长度突增时只扩 decode 池。代价的最终落点是互联带宽与两池副本显存：规模上限受这两者约束，长 prompt 场景下互联带宽是先撞到的墙。因此本算法的工程判断可以归结为一句：拆池的收益来自 SLO 口径的 goodput，成本来自 KV 传输项与副本开销，二者之比由 $\\bar{L}_{\\text{prompt}}$、模型层数与互联带宽共同决定，配比调优必须在这三个量上做，而不是在批次大小上做。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-13\">十三 · 拆池之后的失效边界：KV 搬运、版本错配与小集群的反噬</h3>\n<p>按数据流拆开看，这条链路上真正决定成败的不是两个池各自算得多快，而是三个衔接点：KV 从 prefill 池写入 decode 池 block table 的那一段、两池队列与 SLO 的耦合方式、以及权重版本切换的原子性。首token与完整KV在 prefill 池产出后，KV按层分片经 NVLink/CXL/IB 写入 decode 池，传输与计算流水重叠——重叠只能隐藏“稳态”下的搬运延迟，隐藏不了首块 KV 的到达延迟，因为 decode 的第一层注意力必须等对应层的 KV 落位才能启动。于是端到端首token时延被写成两项之和：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>其中 $S_{\\text{KV}}$ 为单请求KV字节数，$BW_{\\text{interconnect}}$ 为跨池互联带宽。这个式子的工程含义是：拆池把 prefill 池从 decode 的干扰中解放出来，却把一部分 TTFT 预算转移给了互联。长prompt、大模型时传输量可达数百MB/请求，此时第二项不再是可忽略的尾项，而是与 $T_{\\text{prefill}}$ 同量级甚至更大；一旦多个长prompt请求在 prefill 池同时完成、KV 集中涌向 decode 池，互联带宽被瞬时占满，后续请求的 KV 排队，TTFT 直接击穿 SLO。这是本方案最典型的失效模式，且它与批大小无关——两池各自组批再优，也救不了被占满的链路。缓解手段是给 KV 传输设优先级与配额、把长prompt请求的 chunk 完成节奏打散，让 KV 到达曲线平滑，而不是让 prefill 池以最大吞吐一次性倾泻。</p>\n<p>第二个衔接点是版本。训练侧新权重经权重同步通道分别推送两池并按版本号原子切换，原子性只在单池内成立；两池之间没有共同的提交点，就存在一个窗口：prefill 池已切到新版本、decode 池仍在旧版本上自回归。此时同一请求的 prompt 前向与 decode 前向用的是不同权重，产出的样本与训练侧策略不一致，rollout 数据被静默污染——这类错误不报错、不降速，只体现在训练侧的似然偏差上，排查成本极高。工程上必须把“版本号”做成请求级标签：请求进入 prefill 池时绑定版本，KV 写入 decode 池时携带该版本，decode 池拒绝在版本不匹配的 KV 上继续解码，宁可让该请求重排队也不产出错样本。代价是切换期间的在途请求被丢弃重算，切换频率越高、在途请求越多，这部分浪费越大，因此权重推送节奏要与 rollout 批次边界对齐，而不是随训练 step 随时推送。</p>\n<p>第三个边界是规模。两池各持独立副本与调度器，显存总占用上升，部署复杂度上升；在小规模集群上，这种上升不是线性的而是反噬性的：池子小到无法各自组出有意义的批次时，prefill 池的 chunk 批次填不满、decode 池的连续批处理也填不满，两边 SM 利用率同时下降，而 KV 传输开销照付。判断是否该拆的粗略口径可以写成两池计算量之比：</p>\n<div class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>比值远离 1 说明阶段资源需求差异明显，拆池的收益才压得住副本与传输的固定开销；比值接近 1 时，同池拼批互补瓶颈反而更省。另一个约束是规模上限受互联带宽与两池副本显存共同限制：互联带宽决定单位时间能搬多少 KV，副本显存决定每池能驻留多少并发序列，两者任一先饱和，扩容就只增加成本不增加 goodput。因此容量规划要按 $\\text{Goodput}$ 的 SLO 口径做，而不是按单池峰值吞吐相加——被 SLO 判为不合格的请求不计入分子，拆池带来的 TTFT 恶化会直接从 goodput 里扣掉。</p>\n<table class=\"mini\"><thead><tr><th>衔接点</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>KV 跨池传输</td><td>长prompt集中完成，数百MB/请求涌入</td><td>互联带宽占满，TTFT 超 SLO</td></tr><tr><td>权重版本切换</td><td>两池切换不同步，存在在途请求</td><td>样本与训练侧不一致，需丢弃重算</td></tr><tr><td>两池独立副本</td><td>小集群、批次填不满</td><td>显存总占用上升，SM 利用率反降</td></tr></tbody></table>\n<p>把这三条放在一起，适用边界就清楚了：适合大规模集群且阶段资源需求差异明显的 rollout，此时 $C_{\\text{pre}}/C_{\\text{dec}}$ 偏离 1、互联带宽充裕、批次能填满两池；不适合小规模集群或 prompt/输出长度分布接近对称的场景。与同池内拼批互补瓶颈、以 KV 为一级调度对象做全局复用的方案相比，本方案的优势在训练-推理解耦更彻底、扩缩容按阶段独立，代价则全部集中在“跨池”这三个字上——凡是需要跨池搬运的东西，无论是 KV 还是权重版本，都是这条链路上最脆弱的环节，也是工程上必须优先设配额、设版本栅栏、设丢弃策略的地方。</p>\n<h3 id=\"alg-pd-disagg-rollout-sec-14\">十四 · Goodput 与容量配比：两个公式的分母不同</h3>\n<p>分离式 rollout 的收益必须用 SLO 口径的 goodput 衡量，而不是裸吞吐。定义式是 <span class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}]}{T}$$</span> 分子是时间窗 T 内同时满足两个约束的请求计数，注意它是“与”而不是“或”：一个请求 TTFT 达标但 TPOT 抖动，就整条不计入。这个“与”是分离式架构存在的全部理由——混部时 decode 的长尾会同时污染 prefill 的 TTFT 与自身的 TPOT，两个约束耦合在一起，分子被双重惩罚；拆池后两阶段各自组批，约束解耦，分子才有机会接近理论上限。推导的关键一步在于把 goodput 对资源配比求极值：设 prefill 池算力占比为 ρ_pre、decode 池为 ρ_dec = 1 − ρ_pre，则两池的请求到达率必须匹配，否则一侧排队爆炸、另一侧空转。匹配条件写成 <span class=\"formula\">$$\\frac{C_{\\text{pre}}}{C_{\\text{dec}}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</span> 左端是两池单位时间能消化的 token 量之比，右端是负载配方给出的 token 需求之比。这个式子的工程含义是：配比不是拍脑袋定的，而是由 rollout 的 prompt/输出长度分布直接锁定的。RL rollout 的典型形态是长 prompt（环境观测、历史轨迹、工具返回）配中等长度输出，L̄_prompt 往往显著大于 L̄_out，于是 C_pre/C_dec 大于 1，prefill 池需要更多算力——这与“decode 是瓶颈”的直觉相反，也是分离式在 rollout 场景下最容易被配错的地方。举例：若一批 rollout 请求平均 prompt 长度是输出长度的数倍，按 1:1 切分 GPU 会让 prefill 池成为唯一瓶颈，decode 池的 TPOT 余量全部浪费，goodput 分子被 TTFT 项卡死；把配比按上式右移到 prefill 侧，分子才随配比单调上升直到两池同时触到各自的 SLO 边界。代价面很清楚：配比偏移意味着 decode 池副本变小，单池显存要装下更多并发序列的 KV，长输出场景下 decode 池的 batch 上限先于算力触顶。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-15\">十五 · TTFT 分解：传输项是分离式独有的加项</h3>\n<p>分离式的 TTFT 不再是单池的 prefill 时间，而是三段串联：<span class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</span> 其中 S_KV 为单请求 KV 字节数，BW_interconnect 为跨池互联带宽。推导的关键一步是把 S_KV 展开成模型与序列的函数：S_KV ≈ 2 · n_layer · n_kv_head · d_head · L_prompt · b_elem，因子 2 是 K 与 V 两份，b_elem 是 KV 元素字节宽度（FP8 与 NVFP4 档位直接改变这一项，量化档位未在配方中给出，但它是唯一能线性压缩传输项的杠杆）。把展开式代回，传输项随 n_layer、L_prompt 线性增长，这就是“长 prompt、大模型时传输量可达数百MB/请求”的来源：层数多、prompt 长、KV 头维度大，三者相乘把单请求 KV 推到数百 MB 量级，而互联带宽是集群级共享资源，不是单请求独占。工程判断因此落在流水重叠上：机制中 KV 按层分片经 NVLink/CXL/IB 写入 decode 池对应 block table，传输与计算流水重叠——第 l 层的 KV 一旦算完就立即发起传输，decode 池可以在收到前若干层 KV 后就开始首 token 的注意力计算，把串联的 T_prefill + S_KV/BW 压成 max(T_prefill, S_KV/BW) 量级。重叠的粒度是层，不是请求：层粒度太粗则首 token 等待整请求 KV 到齐，太细则传输事务开销吃掉带宽。代价是这条流水要求两池的 block table 布局对齐，decode 池必须预留好目标 block 并提前注册接收缓冲，否则传输落地时要临时分配，重叠失效。失败模式在此显形：KV 跨池传输占满互联带宽时，传输项从被隐藏变成主导项，长 prompt 场景 TTFT 直接超出 SLO，且这种超支不会体现在任何单池的算力指标上，只能从互联利用率看出来。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-16\">十六 · 两池独立组批的伪代码骨架</h3>\n<p>把机制落到可实现，关键是两池各自持有队列、各自按自己的 SLO 触发组批与扩缩容，中间只通过 KV 传输通道与版本号耦合。伪代码思路如下（非 <pre>，以文字描述控制流）：prefill 池主循环每次从队列取请求，按 chunk 组批，对每个 chunk 做全 prompt 前向，产出首 token 并写入本池的 KV 缓冲；随后对该请求的每一层 KV 发起异步传输，目标地址由 decode 池预先分配的 block table 条目给出，传输句柄挂到该请求的完成计数上；当完成计数等于层数时，向 decode 池的就绪队列投递一条“KV 齐备”事件，携带请求 id、首 token、目标 block 列表与权重版本号。decode 池主循环只做一件事：从就绪队列取事件，把该请求挂进纯 decode 批次，连续自回归直到 EOS 或长度上限，每步只读本地 KV，不回头访问 prefill 池。两池的扩容判据分离：prefill 池监控队列等待时间对 TTFT 目标的余量，decode 池监控每步耗时对 TPOT 目标的余量，各自独立增减实例。推导的关键一步在“就绪事件”的原子性：事件必须同时携带权重版本号，decode 池在挂批前比对本地版本，不一致则拒绝该请求并回退到 prefill 池重算——这是防止两池版本错配的唯一硬约束。代价面：prefill 池的 KV 缓冲在传输完成前不能释放，等于在 prefill 池显存里额外驻留一份在途 KV，在途请求数越多，这份影子显存越大；decode 池则要为每个未就绪请求预留 block，预留期间这些 block 不可被其他序列复用，分页利用率下降。举例：当互联带宽吃紧、传输队列积压时，prefill 池会同时持有大量在途 KV 与等待组批的新请求，显存先于算力成为瓶颈，此时扩容 prefill 池反而加剧拥塞，正确动作是限流而非加卡。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-17\">十七 · 权重版本切换的原子性推导</h3>\n<p>RL rollout 的特殊约束是训练侧持续产出新权重，rollout 引擎必须快速换权重，而分离式把这件事从“一次切换”变成“两次切换加一次一致性校验”。设 prefill 池版本为 v_p、decode 池版本为 v_d，样本一致性要求 v_p = v_d = v_train 对每个被采样的请求成立。推导的关键一步是把请求生命周期切成三段：prefill 前向、KV 在途、decode 自回归。切换只能发生在段边界，不能跨段：若在 KV 在途时 prefill 池切到新版本，decode 池仍用旧版本消费这份 KV，则同一请求的 KV 由两套权重共同决定，样本既不属于旧策略也不属于新策略，梯度估计有偏。因此协议必须是：新权重先推送到两池的暂存区，两池各自在“当前批次排空”后原子地把版本号从 v 翻到 v+1，翻转动作对调度器可见；调度器在翻转窗口内暂停跨池投递，窗口长度等于最长在途 KV 的传输时间。代价是这段暂停直接体现为 goodput 的空洞：翻转频率越高，空洞占比越大，而 RL 训练的权重更新节奏恰恰不低。工程上把翻转窗口与传输流水对齐——让最后一层 KV 的传输完成事件成为翻转的触发点，可以把窗口压到单请求传输时延量级。失败模式是两池权重版本切换不同步：decode 池用旧权重产出与训练侧不一致的样本，这类样本在训练侧表现为策略梯度与重要性采样比的系统性偏差，且不会在推理侧的任何延迟指标上报警，只能靠版本号审计发现。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-18\">十八 · 传输量与显存总占用的联合约束</h3>\n<p>分离式的规模上限由两个不等式共同决定，而不是单一维度。第一个是带宽约束：集群互联总带宽 BW_total 要同时承载 KV 传输与权重同步，稳态下 KV 传输占用为 Σ_i S_KV,i / T，若该值逼近 BW_total，传输项从被重叠隐藏变为显性瓶颈，TTFT 失控。第二个是显存约束：两池各持独立副本，权重显存翻倍，加上 prefill 池的在途 KV 影子副本与 decode 池的预留 block，总显存占用高于同规模混部。把两式联立可得规模上限的定性结论：可支撑的并发 rollout 请求数受 min(BW_total · T / S̄_KV, 可用显存 / 单请求显存足迹) 约束，前者随 prompt 长度恶化，后者随输出长度恶化——长 prompt 打带宽，长输出打显存，两类负载的瓶颈不同，这解释了为什么配比必须按负载配方动态调。代价在小规模集群上直接翻转：两池独立副本使显存总占用上升，当集群规模不足以让两池都跑到高效 batch 区间时，单池的 batch 效率损失超过分离带来的干扰消除收益，资源利用率反而下降，这是“小规模集群不划算”的定量根因，而非经验之谈。举例：一个刚好装下混部引擎的集群，拆池后每池只剩一半显存，decode 池的并发序列数减半，TPOT 因 batch 变小而恶化，goodput 分子不升反降。工程判断因此是：分离式的门槛不是“有没有互联”，而是“拆池后两池是否都还能维持各自的 SLO 内 batch 规模”，达不到就不拆。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-19\">十九 · 与相邻算法的公式级分野</h3>\n<p>同一批公式在相邻算法里被改写，分野可以精确到项。分块预填背驮解码在同池内拼批，它的 TTFT 公式没有 S_KV/BW 这一项，代价换成 decode 批次被 prefill chunk 打断带来的 TPOT 抖动；KV 中心分离式池化把 KV 作为一级调度对象，S_KV 的搬运发生在池内而非跨池，带宽项被池内高带宽吃掉，但引入了全局 KV 目录的查找延迟；本算法按阶段拆池，S_KV/BW 是显式代价，换来的是两池独立扩缩容与训练-推理解耦。公式级的分野在于 goodput 分子的约束结构：同池方案里 TTFT 与 TPOT 共享同一组资源，两约束在时间上耦合，优化其一是零和的；拆池后两约束分属不同资源池，可以同时逼近各自边界，这是分离式唯一不可替代的性质。伪代码层面的分野在于就绪事件的语义：同池方案的就绪是“本地 KV 可用”，拆池方案的就绪是“跨池 KV 齐备且版本一致”，后者多了一次版本比对与一次传输完成计数，这两步是分离式调度器必须实现而不能省略的。代价的最后一条落在部署复杂度上：两池需独立副本与调度器，权重同步通道要覆盖两个目标，运维面翻倍；当互联带宽与两池副本显存任一触顶，分离式的收益被代价吞掉，此时应退回同池拼批方案，而不是继续加池。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-20\">二十 · 跨池传输项如何吃掉 TTFT 预算</h3>\n<p>把分离式 rollout 的 TTFT 拆开看，只有一项是混部方案里不存在的：$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$。前一项由 prefill 池的算力与组批效率决定，后一项是纯搬运成本，分子 $$S_{\\text{KV}}$$ 随层数、KV 头数、头维度与 prompt 长度线性增长，分母是跨池互联的实际可用带宽——注意是\"可用\"，不是标称，因为同一张网卡上还跑着权重同步、其他请求的 KV 分片以及集合通信。推导的关键一步在于：流水重叠只能隐藏传输的**稳态**部分，不能隐藏**首块**。decode 池必须等到第 0 层到第 n 层的 KV 全部落位才能开始自回归，因此即便按层分片、传一层算一层，首个 decode step 仍被首层 KV 的到达时刻卡住；重叠把 $$S_{\\text{KV}}/BW$$ 从串行延迟压缩成\"首片延迟 + 尾部残余\"，但长 prompt 下首片本身就够大。工程判断很直接：当 $$S_{\\text{KV}}/BW_{\\text{interconnect}}$$ 逼近 TTFT SLO 的余量时，这个方案在该负载配方上失效，此时要么缩 chunk、要么把 prefill 池与 decode 池拉近到同一 NVLink 域。</p>\n<p>伪代码层面，失效条件必须写成可判定的门限而不是感觉：</p>\n<ul>\n<li>prefill 池：按 chunk 组批跑完 prompt 前向，得首 token 与逐层 KV 分片，写入发送队列并打上权重版本号 v。</li>\n<li>传输层：按层发起异步写，与下一 chunk 的 prefill 计算重叠；维护在途字节计数 inflight_bytes。</li>\n<li>decode 池：block table 按层登记到达的分片，全部层就绪才把请求插入连续批；若 inflight_bytes 超过互联带宽预算的份额，暂停接纳新请求而非降级已有请求。</li>\n<li>权重切换：两池各自收到版本 v+1 后原子切换，切换窗口内新请求只进不出，避免 decode 池用旧权重产出与训练侧不一致的样本。</li>\n</ul>\n<p>系统代价要按池分别记，不能只记总算力。prefill 池的瓶颈是算力与 TTFT 队列，decode 池的瓶颈是显存带宽与 TPOT，两池独立副本意味着显存总占用上升，小规模集群下副本开销摊不薄，利用率反而下降。互联带宽成了新的全局稀缺资源：数百 MB/请求的传输量在长 prompt、大模型配方下会与权重同步争抢同一条链路，权重切换期间尤其危险——此时 KV 传输与权重推送叠加，TTFT 抖动最明显。可行的缓解是把权重同步安排在 KV 传输的低谷窗口，或为权重通道预留固定带宽份额，让 KV 传输项在公式里有一个可预测的上界。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>KV 传输占满互联</td><td>inflight_bytes 持续贴顶、TTFT 超 SLO</td><td>限流接纳、缩 chunk、拉近两池拓扑</td></tr><tr><td>两池版本错配</td><td>decode 输出与训练侧不一致</td><td>版本号原子切换、切换窗口冻结新请求</td></tr><tr><td>副本开销压过收益</td><td>显存总占用上升、goodput 不升</td><td>退回同池分块预填背驮解码</td></tr></tbody></table>\n<h3 id=\"alg-pd-disagg-rollout-sec-21\">二十一 · 什么请求形态才配得上拆池</h3>\n<p>预填解码分离不是通用加速器，它对请求形态有明确的“口味偏好”。把请求拆成两段看：prompt 长度 $\\bar{L}_{\\text{prompt}}$ 与输出长度 $\\bar{L}_{\\text{out}}$。分离的收益来自两池各自组批后瓶颈互不污染——prefill 池吃的是算力密集的矩阵乘，decode 池吃的是带宽密集的逐 token 自回归。只有当两阶段的资源需求比例在时间上稳定、且各自都能被独立喂饱时，拆池才划算。核心判据是两池的负载配比：</p>\n<div class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>其中 $\\rho_{\\text{pre}}$、$\\rho_{\\text{dec}}$ 是两阶段的到达率。这个比值告诉你 prefill 池与 decode 池的 GPU 数量该按什么比例配。若 $\\bar{L}_{\\text{prompt}}$ 远大于 $\\bar{L}_{\\text{out}}$（长 prompt、短输出，如检索增强的单轮问答、分类打分），配比偏向 prefill 池；若输出远长于 prompt（长思维链、代码生成、多轮 agent 轨迹），配比偏向 decode 池。RL rollout 的典型形态恰恰是“长 prompt + 长输出”混合：训练样本的 prompt 往往是拼接了上下文与指令的长序列，输出则是完整的推理轨迹，两端都长，于是两池都得给足资源，拆池的固定成本（两套副本、两套调度器）才有摊薄的空间。</p>\n<p>反面形态同样清晰。短 prompt、短输出的高频小请求，单请求 KV 只有几 MB 量级，跨池传输项 $\\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$ 虽小，但两池各自的调度开销与队列空转占比上升，拆池带来的 TTFT 增益被固定开销吃掉。更关键的是并发：分离架构要求两池同时有足够多的在途请求把批次填满。prefill 池按 chunk 组批，若到达率低到每批只有个位数请求，算力利用率塌陷；decode 池的连续批处理同样需要足够多的活跃序列维持 batch 维度。低并发下拆池是把一个能跑满的混部池硬拆成两个都跑不满的池，显存总占用翻倍而吞吐不增。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-22\">二十二 · 长度分布决定配比，而不是平均值</h3>\n<p>只盯均值会误判。设 prompt 长度服从重尾分布，少数超长 prompt（数十万 token）与大量短 prompt 共存，prefill 池的组批策略必须按 chunk 切分把长 prompt 拆成定长块，否则一个超长请求会独占整个批次、把同批其他请求的 TTFT 拖爆。此时 prefill 池的有效吞吐由“块数”而非“请求数”决定，扩容依据应是块到达率。decode 池同理：输出长度分布的重尾意味着少数长轨迹会长期占用 KV block，decode 池的显存水位由在途长序列的 KV 总量决定，而非平均输出长度。</p>\n<p>工程上的做法是把长度分布直接喂进配比公式的分位数版本：用 $\\bar{L}_{\\text{prompt}}$ 的 P90 而非均值估算 prefill 池的峰值算力需求，用 $\\bar{L}_{\\text{out}}$ 的 P90 估算 decode 池的 KV 显存峰值。代价是资源冗余——按 P90 配比意味着多数时段有闲置，但按均值配比会在重尾尾部频繁触发 SLO 违约。RL rollout 的场景里，训练侧对样本时延的容忍度通常高于在线服务，因此可以把配比压到 P75 附近，用排队而非扩容吸收尾部，这是分离架构相对混部的一个隐性优势：两池可以各自选择不同的超配策略，prefill 池超配算力、decode 池超配显存，互不牵制。</p>\n<p>具体例子：一批 rollout 请求中 prompt 长度跨度从数千到数十万 token，输出长度从数十到数千 token。按均值配比会把 prefill 池配小，长 prompt 请求在 prefill 队列里排队，TTFT 直接越过 SLO；而 decode 池因长输出序列的 KV 累积，显存先于算力成为瓶颈，TPOT 因 block 分配失败而抖动。正确做法是两池分别按各自长度的 P90 定容，并在 prefill 池启用 chunk 组批把长 prompt 的块均匀铺开。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-23\">二十三 · 批大小两池独立，但独立不等于随意</h3>\n<p>分离架构的卖点之一是两池批大小解耦：prefill 池按 chunk 组批追求算力打满，decode 池按连续批处理追求 TPOT 稳定。但批大小并非自由变量，它被三个约束夹住。其一是 KV 传输的流水重叠深度：prefill 池产出的 KV 按层分片写入 decode 池的 block table，传输与计算重叠要求 decode 池预留足够的接收缓冲，批越大，单批 KV 字节数越大，缓冲占用与传输抖动越难隐藏。其二是 decode 池的显存：批大小 × 平均序列长度 × 每 token KV 字节数构成常驻占用，批大小翻倍意味着 KV block 池翻倍，在长输出场景下这是显存的第一约束。其三是权重切换的原子性：两池按版本号原子切换权重，切换瞬间两池都必须排空在途批次或做双版本共存，批越大，排空窗口越长，切换期间的有效吞吐越低。</p>\n<p>因此批大小的调优目标是让“传输隐藏率”与“显存水位”同时达标，而不是单纯追大。一个可操作的伪代码思路：</p>\n<ul>\n<li>prefill 池：以 chunk 大小为组批粒度，块数上限由目标 TTFT 反推，块数 × 单块前向时延 ≤ $S_{\\text{ttft}}$ 减去传输项；</li>\n<li>decode 池：批大小上限由 KV block 池容量除以 P90 序列长度得出，再乘以一个小于 1 的安全系数留给权重切换时的双版本共存；</li>\n<li>两池批大小独立设定，但共享同一个版本号与排空屏障，切换时两池同时停止接纳新批。</li>\n</ul>\n<p>代价体现在延迟上：decode 池批大小被显存压住后，单批 token 吞吐下降，TPOT 的均值可能变差，但因为消除了长 prompt 插入造成的批内抖动，TPOT 的 P99 反而收敛。这正是分离架构在 SLO 口径下的价值——goodput 按 $\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}$ 计数，尾部收敛比均值优化更能提升计数。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-24\">二十四 · 并发水位与两池队列的耦合</h3>\n<p>两池各自维护队列与 SLO，但队列之间通过 KV 传输耦合。prefill 池完成一个请求就向 decode 池投递一份 KV，decode 池的接纳能力反过来限制 prefill 池的产出节奏——若 decode 池的 KV block 池满，prefill 池必须背压，否则传输会阻塞在互联上。这个背压链路的稳定性取决于并发水位：并发太低，两池都喂不饱；并发太高，背压振荡导致 prefill 池的批次时开时停，chunk 组批的效率骤降。</p>\n<p>稳定工作点出现在“decode 池的 KV 释放速率 ≈ prefill 池的 KV 注入速率”附近。释放速率由 decode 池的 token 生成速率与 EOS 到达率决定，注入速率由 prefill 池的块完成速率决定。工程上用一个水位信号做闭环：decode 池的 KV block 占用率超过阈值就向 prefill 池发背压，低于阈值就放开。这个信号必须比权重切换的排空屏障优先级低，否则切换期间会出现背压与排空互相等待的死锁。具体例子：长输出 rollout 场景下，decode 池的 KV 占用率随在途长轨迹缓慢爬升，若不做背压，prefill 池持续注入直到 decode 池 OOM，触发一次全局重调度，所有在途请求的 TPOT 集体违约；加了水位背压后，prefill 池在占用率触及阈值时降速，TTFT 略微上升但 TPOT 保持稳定，goodput 反而更高。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-25\">二十五 · 负载不对时的三种塌陷</h3>\n<p>负载配方错配不会温和退化，而是以三种可辨识的方式塌陷。第一种是传输项主导：长 prompt、大模型下单请求 KV 可达数百 MB，跨池互联带宽被 KV 搬运占满，$\\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$ 在 TTFT 中占比超过前向计算本身，prefill 池算得再快也没用，TTFT 直接越过 SLO。此时拆池的收益为负——混部至少不用付这笔传输。判据是传输项与前向时延的比值，超过阈值就该退回同池或改用 KV 中心池化。</p>\n<p>第二种是权重版本错配：两池按版本号原子切换，但切换通道的带宽有限，prefill 池与 decode 池的切换完成时刻存在偏差。若 decode 池仍用旧权重自回归，产出的样本与训练侧当前策略不一致，RL 的 on-policy 假设被破坏，样本梯度带偏。这不是性能问题而是正确性问题，代价是训练收敛变慢甚至发散。防护手段是切换期间两池共享同一个版本屏障，decode 池拒绝接纳旧版本 KV，prefill 池在屏障未放行前不产出新批。</p>\n<p>第三种是小规模集群的资源倒挂：两池各持独立副本与调度器，显存总占用接近翻倍，而集群规模不足以让两池都跑满，资源利用率反而低于混部。适用边界写得很清楚——适合大规模集群与阶段资源需求差异明显的 rollout，规模上限受互联带宽与两池副本显存约束。判断是否值得拆池，先算两池在目标并发下的稳态占用率，任一池低于有效水位就不该拆。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-26\">二十六 · 配方落地：从分布到配比到扩缩容</h3>\n<p>把负载配方写成可执行的工程判断，顺序是：先测长度分布的分位数，再定两池配比，再定各自批大小上限，最后接扩缩容信号。配比按 $C_{\\text{pre}}/C_{\\text{dec}}$ 的分位数版本给出初始值；批大小按第三节的约束反推；扩缩容信号分别是 prefill 池的 TTFT 违约率与 decode 池的 TPOT 违约率，两者独立触发、独立扩容，这正是分离架构相对混部的核心弹性来源——混部时一次扩容要同时照顾两个相反的瓶颈，分离后各管各的。</p>\n<p>权重切换的频率必须进入配方。RL rollout 的训练侧权重更新节奏决定了排空窗口的占空比：切换越频繁，两池的有效计算时间越短，批大小与并发水位都要留出更大的安全系数。若切换间隔短到排空窗口占比可观，分离架构的固定开销开始显性化，此时应拉长切换周期或改用双版本共存的滚动切换，而不是缩小批大小硬扛。最后一条工程判断落在互联带宽上：KV 传输项是分离架构的硬约束，配比与批大小的所有调优都不能突破 $\\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$ 给出的 TTFT 下限，负载配方本质上是在这个下限之上分配两池的资源。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-27\">二十七 · 负载配方与失效边界：什么时候这套拆池方案会反噬</h3>\n<p>分离式预填/解码的收益不是无条件成立的，它由一条配比关系锁定：<div class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>左侧是两池的算力配比，右侧由请求到达率与平均 prompt/输出长度决定。rollout 负载若偏离这一配比——例如长 prompt 短输出的\"判题式\"采样，或短 prompt 长推理链的采样——两池中总有一侧成为空转的静态预留。此时即便单池组批再干净，goodput 仍被闲置池的固定开销拖住，因为池子按阶段切分后无法把空闲算力借给另一阶段。这正是混部方案在负载漂移时反而更稳的原因：它至少能靠拼批互补瓶颈。</p>\n<p>KV 跨池搬运是第二个硬边界。首 token 延迟被传输项直接抬高：<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>长 prompt、大模型下单请求 KV 可达数百 MB，若互联带宽被并发请求的搬运同时占满，TTFT 会整段超出 SLO，而 prefill 池的扩容对此无能为力——瓶颈不在算力而在链路。工程上的判别方法是把 $\\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$ 与 $T_{\\text{prefill}}$ 做量级对比：传输项一旦与计算项同阶，流水重叠只能隐藏一部分，剩余部分直接计入 TTFT 违约。</p>\n<p>第三类失效来自权重版本。两池各持独立副本，训练侧更新须经同步通道分别推送并按版本号原子切换；若切换不同步，decode 池会用旧权重继续自回归，产出与训练侧策略不一致的样本，污染 rollout 数据。这不是性能问题而是正确性问题，因此版本号必须作为批次元数据随请求透传，decode 侧拒收版本不匹配的 KV。小规模集群还面临第四重代价：两池独立副本使显存总占用上升，资源利用率反而下降，规模上限同时受互联带宽与两池副本显存约束。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>配比倾向</th><th>主要风险</th></tr></thead><tbody><tr><td>长 prompt、长输出混合</td><td>两池均重，可按分布调优</td><td>KV 传输量最大，TTFT 易违约</td></tr><tr><td>长 prompt、短输出</td><td>prefill 主导</td><td>decode 池闲置，配比失衡</td></tr><tr><td>短 prompt、长输出</td><td>decode 主导</td><td>prefill 池扩容收益递减</td></tr></tbody></table>\n<p>因此适用判断应落在两句话上：集群规模足够大、且 rollout 的阶段资源需求差异明显到值得为两池分别选档位与并行拓扑时，拆池的独立扩缩容与训练-推理解耦才付得起部署复杂度；反之，请求长度分布集中、互联带宽不富裕的小集群，应退回同池拼批，把 KV 搬运成本留在零。</p>\n<h3 id=\"alg-pd-disagg-rollout-sec-28\">二十八 · 硬件档位：两池不同代际、不同形态的取舍</h3>\n<p>分离式部署的第一条硬约束是：prefill池与decode池不必是同一档 GPU。prefill 是计算密集型阶段，受矩阵乘吞吐与 chunk 调度效率支配，对显存容量的要求相对温和——它只需容纳权重分片、当前 chunk 的激活与刚产出的 KV 切片，KV 写完即可释放。decode 则是带宽与容量密集型阶段，每步只算一个 token，却要把整个 KV cache 常驻在 HBM 里，TPOT 直接由 HBM 带宽与 KV 读取量决定。因此一个自然的档位配方是：prefill 池用高算力档（B200 级、甚至以 FP8/NVFP4 峰值吞吐为导向配置），decode 池用大容量、高带宽档（B300 级或 GB300 NVL72 机柜形态），把 HBM 容量预算优先给 KV 而非给权重冗余。</p>\n<p>档位差异带来一个必须显式处理的工程后果：两池的权重副本格式可以不同。prefill 池可以吃更激进的量化档位以换取 chunk 吞吐，decode 池则要考虑低精度下逐 token 自回归的数值稳定性（该问题在 NVFP4 量化 Rollout 稳定化条目中展开，此处只作指路）。若两池量化档位不一致，权重同步通道就必须做一次格式转换，转换成本计入权重切换窗口，不能假设“推过去就能用”。</p>\n<p>代价口径上，档位异构的直接收益是资源配比可按 prompt/输出长度分布调优，直接代价是备件与运维复杂度上升：两套驱动、两套编译产物、两套健康检查。规模不足时，这种异构带来的显存总占用上升会吃掉收益——小规模集群下两池独立副本使显存总占用接近翻倍，利用率反而下降，这是本算法适用边界里最硬的一条。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-29\">二十九 · 并行拓扑：两池各自独立成型</h3>\n<p>并行拓扑必须解耦，这是分离式相对混部最实质的自由度。prefill 池的瓶颈是单请求长 prompt 的 chunk 前向效率，拓扑倾向于较大的 TP 组以压低单 chunk 延迟，同时用 DP 复制承接并发请求数；由于 prefill 不持有长期 KV，EP（专家并行）在 MoE 模型上可以把权重摊薄到更多卡上而不必担心 KV 分片错配。decode 池的拓扑则由 KV 的分布决定：KV 按层分片跨池传输，落到 decode 池后必须与 decode 侧的 attention 切分方式对齐，因此 decode 池的 TP 组大小实际上被“KV 分片粒度”反向约束——prefill 侧按什么粒度切层、按什么布局写 block table，decode 侧就必须以兼容的 TP/attention 头切分去读。</p>\n<p>一个可复现的配置思路是把拓扑写成两行独立参数，而不是一个全局并行度：</p>\n<div class=\"formula\">$$\\text{TP}_{\\text{pre}},\\,\\text{DP}_{\\text{pre}},\\,\\text{EP}_{\\text{pre}} \\;\\perp\\; \\text{TP}_{\\text{dec}},\\,\\text{DP}_{\\text{dec}},\\,\\text{KV}_{\\text{shard}}$$</div>\n<p>其中 KV_shard 是跨池传输的分片数，它同时是 prefill 的写粒度与 decode 的读粒度，必须整除 decode 侧 attention 的头数或层组。伪代码层面的校验逻辑是：在引擎启动时对 (TP_dec, KV_shard) 做一次整除断言，不满足则拒绝启动，而不是等到第一个请求传输时才发现布局错配——后者会把错误暴露在 TTFT 上，表现为个别请求的传输项异常拉长。</p>\n<p>代价上，拓扑独立意味着两池的通信域也独立：prefill 池内部的 TP 集合通信与 decode 池内部的 all-reduce 各自走各自的 NVLink 域，跨池只走 KV 传输通道。这降低了集合通信的耦合，但也意味着两池之间没有“顺带”的带宽复用，KV 传输必须实打实占用互联带宽预算。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-30\">三十 · 量化方案：按阶段分配精度预算</h3>\n<p>量化档位在分离式里不是全局开关，而是按阶段分配的预算。prefill 的 GEMM 是大矩阵乘，NVFP4/FP8 的吞吐收益可以直接兑现，且误差在长 prompt 的聚合中被平均掉一部分；decode 的每步计算量小、KV 读取占主导，权重精度对 TPOT 的影响远小于 KV 精度对 TPOT 的影响，因此 decode 侧的量化决策应优先落在 KV cache 的存储精度上，而不是权重上。一个实用的分配是：prefill 权重走低精度高吞吐档，decode 权重保持较高精度以稳住逐 token 分布，KV 以分片为单位选择存储精度，长上下文请求用较低精度 KV 换容量。</p>\n<p>这里有一个跨池一致性问题：prefill 产出的 KV 是以某种精度写出的，decode 读入时必须知道这个精度并按同一布局解释。若两池量化档位不同，KV 在传输路径上需要一次精度转换，转换要么在 prefill 写出前做（增加 prefill 计算量），要么在 decode 读入后做（增加 decode 每步开销）。前者污染 TTFT，后者污染 TPOT，二者必选其一，配置时必须显式记录这个选择而不是让它隐式发生。</p>\n<p>代价口径：低精度 KV 直接换容量，容量换的是 decode 池可承载的并发序列数，进而换吞吐；但精度下降会改变采样分布，rollout 样本与训练侧的一致性风险上升。这个权衡在 NVFP4 稳定化条目里有专门讨论，此处只强调一点——分离式让两池可以选不同档位，但“不同”本身要付转换成本，档位差异越大，转换越贵。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-31\">三十一 · KV 策略：分片、流水重叠与容量水位</h3>\n<p>KV 策略是这套部署配方里最需要精细化的部分，因为跨池传输项直接进 TTFT：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>配方上要压的是第二项。三条手段：其一，按层分片传输，让 decode 侧在收到前若干层 KV 时就能开始该层的 attention 准备，把“全量到达才启动”变成“逐层就绪逐层推进”；其二，传输与计算流水重叠——prefill 在算第 k 个 chunk 时，第 k−1 个 chunk 已产出的 KV 分片正在链路上，链路占用被计算时间掩盖；其三，控制单请求 KV 字节数，长 prompt、大模型时传输量可达数百MB/请求，这类请求必须走“分片+重叠”路径，否则单请求就能把互联带宽占满，把同批其他请求的 TTFT 一起拖出 SLO。</p>\n<p>decode 池侧的 KV 策略是容量水位管理。decode 池持有全部活跃序列的 KV，其容量上限决定最大并发批，而并发批决定 TPOT 能否守住。配置时要设两个水位：软水位触发向调度器反馈“停止接纳新序列”，硬水位触发抢占或驱逐最长序列。水位参数与 prefill 池的扩容阈值必须联动——prefill 池按 TTFT 目标扩容时若不同步检查 decode 侧水位，会把请求推进一个已经满的池子，表现为 TTFT 达标但请求在 decode 队列里排队，goodput 口径下这些请求仍然失败。</p>\n<p>代价：分片传输增加了协议开销与乱序重组的复杂度；流水重叠要求 prefill 侧保留刚产出的 KV 切片直到确认写出，抬高了 prefill 池的瞬时显存占用；水位管理引入抢占，被抢占序列的 KV 需要重算或换出，两者都计入有效吞吐损失。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-32\">三十二 · 调度参数：两套 SLO 队列与权重版本闸门</h3>\n<p>两池各持独立调度器，参数必须成对给出而不是单点调优。prefill 池的核心参数是 chunk 大小与批内 chunk 数：chunk 太小则单 chunk 计算效率低、传输分片过碎；chunk 太大则单请求占用 prefill 资源过久，TTFT 尾部拉长。decode 池的核心参数是连续批处理的最大批与每步 token 预算，批越大 TPOT 越稳但单步延迟上升，需按 TPOT 目标反解。</p>\n<p>权重版本闸门是分离式独有的调度参数。训练侧新权重经权重同步通道分别推送到两池，按版本号原子切换；调度器必须拒绝跨版本混跑——若 prefill 池已切到 v+1 而 decode 池仍在 v，decode 用旧权重产出的 token 与训练侧不一致，rollout 样本被污染且难以事后检测。可复现的做法是：两池各自维护 current_version，调度器在接纳请求时携带版本标签，KV 传输消息头里带上产出该 KV 的版本号，decode 侧收到版本号与自身 current_version 不符的 KV 时直接丢弃并回退请求，而不是静默拼接。切换窗口内应暂停接纳新请求或将其路由到仍处旧版本的副本，把“原子”落实到请求粒度而非进程粒度。</p>\n<p>代价：版本闸门在切换瞬间制造一个短暂的接纳空窗，空窗长度等于最慢一池的权重加载时间；对高频权重更新的 RL 训练，这个空窗会周期性吃掉一部分 goodput。因此权重推送应尽量走增量/分片加载并与在途请求的排空重叠，把空窗压到接近单池加载时间。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-33\">三十三 · 可复现的配置思路：从长度分布反解配比</h3>\n<p>把上述五项收束成一条可复现的推导链，起点是负载的长度分布而非硬件清单。给定 rollout 的 prompt 长度均值与输出长度均值，两池的算力配比由下式给出：</p>\n<div class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>先按此式定两池的卡数比例，再在此比例下选档位：prefill 侧取算力档、decode 侧取容量带宽档。随后按单请求 KV 字节数与互联带宽估算传输项，检查它是否吃掉 TTFT 预算的显著份额——若吃掉，则加大分片数、开启流水重叠、并对超长 prompt 单独设一条低速通道以免污染主通道。最后设调度参数：prefill 的 chunk 大小按 TTFT 目标反解，decode 的最大批按 TPOT 目标与 KV 容量水位反解，两池的扩容阈值与水位联动，权重版本闸门默认开启。</p>\n<p>验证这套配方是否成立，用 goodput 口径而非平均延迟：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}]}{T}$$</div>\n<p>配置调优的每一步都应观察这个量而非均值——分离式最容易出现的失效不是平均变慢，而是尾部请求因 KV 传输占满带宽而整体跌出 SLO，均值看不出、goodput 看得出。一个具体的判断点是：当长 prompt 请求占比上升时，若 goodput 下降而两池平均利用率都不高，说明瓶颈在互联带宽而非算力，此时加卡无效，应调分片与重叠参数或对长 prompt 限流。反过来，若 decode 池水位长期贴硬水位而 prefill 池空闲，说明配比公式里的长度均值估计偏低，应按实际分布重算 C_pre/C_dec 而不是给 decode 池加调度技巧。</p>\n<p>这套配方的复现性来自它只依赖四个可观测量：prompt/输出长度分布、单请求 KV 字节数、互联带宽、两池各自的 SLO 阈值。四个量都可从线上采样得到，配置由此反解而非凭经验试凑；档位异构、拓扑独立、量化分阶段、KV 分片流水、版本闸门这五项则是这条推导链上必须显式落地的工程决策点，任何一项缺省都会在 goodput 上以尾部失败的形式暴露出来。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-34\">三十四 · 分离式 Rollout 的失效边界与配比校准</h3>\n<p>这套配方的成立前提是两池的瓶颈互不重叠：prefill 池吃满 tensor core 算力，decode 池吃满 HBM 带宽与 KV 容量，一旦某一侧的空闲资源无法被另一侧借用，独立扩缩容就从优势变成浪费。判断边界用配比式：<div class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>其中 $\\rho$ 为两池各自的请求到达率。当 rollout 的 prompt/输出长度分布剧烈漂移（例如课程学习后期输出长度陡增），配比需要跟着重算；配比失准的直接代价是 decode 池排队、TPOT 超出 SLO，而 prefill 池空转，goodput 按 SLO 口径反而低于混部。工程上应把该比值做成在线指标而非静态配置，按滑动窗口的长度分布定期重算两池实例数。</p>\n<p>KV 跨池传输是第二个硬边界。单请求 KV 字节数随层数、头数、序列长度线性增长，长 prompt、大模型场景下单请求可达数百 MB；TTFT 因此被拆成两段：<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>传输项只能靠流水重叠隐藏，不能消除。当互联带宽被并发请求的 KV 搬运占满时，prefill 池产出的 KV 堵在出口，TTFT 直接击穿 SLO——这是长 prompt 场景最典型的失效模式。配方上应给 KV 传输设独立带宽配额与并发上限，并在 prefill 池侧按 chunk 粒度控制同时在传的请求数，避免传输队列反压计算队列。</p>\n<p>权重同步是第三个失效点，且它不体现在延迟指标上，而是污染样本。两池各持独立副本，训练侧新权重必须经同步通道分别推送并按版本号原子切换；若 decode 池切换滞后于 prefill 池，同一批 rollout 会出现“新 prompt 编码 + 旧权重解码”的错配样本，梯度方向被系统性带偏。配方要求版本号随 KV 一起传递，decode 池拒收版本号低于本地权重的 KV 块，宁可丢弃重算也不混版。代价是切换窗口内的请求丢弃率上升，因此切换频率应与 rollout 批次边界对齐，而非按固定时间间隔。</p>\n<p>最后是规模下限。两池独立副本与调度器使显存总占用上升，小规模集群下副本开销占比过高，资源利用率反而下降；该方案适合大规模集群与阶段资源需求差异明显的 rollout，规模上限同时受互联带宽与两池副本显存约束。落到具体判断：若单次 rollout 批的 KV 传输总量相对互联带宽的占用时间已接近 TTFT 预算的可观比例，或两池副本显存之和超过单池混部方案的可承载模型规模，就应退回同池方案，用分块预填背驮解码在池内互补瓶颈，而不是强行拆池。</p>\n<h3 id=\"alg-pd-disagg-rollout-sec-35\">三十五 · 互联带宽成为TTFT的第一约束项</h3>\n<p>分离式预填/解码的代价结构里，最容易被低估的是跨池KV搬运。前文给出的核心式子是</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>把它拆开看：prefill池的算力可以靠堆GPU线性缩短，但传输项只由单请求KV字节数与互联带宽决定，与池子规模无关。也就是说，prefill池扩容到某个点之后，TTFT的下降曲线会被这一项压平——这是分离式架构第一个“规模上去先崩”的位置。单请求KV字节数随层数、KV头数、头维度、prompt长度线性增长，长prompt、大模型场景下单请求传输量可达数百MB量级。以数百MB除以一条NVLink链路的有效单向带宽，传输项落在毫秒到十毫秒量级；若走IB跨节点，有效带宽更低且受多租户争用，这一项会直接吃掉TTFT预算的一大块。</p>\n<p>工程上的应对不是“买更快的网”，而是把传输从关键路径上摘出去。机制上，KV按层分片写入decode池对应block table，第l层的KV一旦到达即可参与该层的decode计算，于是第l+1层的传输与第l层的decode在时间上重叠。伪代码思路是：prefill池每完成一层就把该层KV切片推入发送队列并置就绪位；decode池的调度器以“已就绪层数”为门槛推进自回归，而不是等整请求KV齐备。代价是decode池需要维护部分就绪的请求状态，调度器复杂度上升，且首token的发射时刻被最慢那一层的到达时间决定——尾延迟由分片传输的最大值而非均值决定。</p>\n<p>具体例子：一个长prompt请求在prefill池完成全prompt前向后，若整块KV一次性搬运，decode池必须空等传输完成才能发首token；改为按层流水后，decode池在最早到达的若干层上就开始推进，首token提前到“第一层KV到达+该层decode时间”，但若互联出现拥塞导致某一层分片迟到，整个请求的TTFT仍被这一片拖住。这就是为什么分离式部署必须把互联带宽当作一等资源做配额，而不是当作背景设施。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-36\">三十六 · 显存总占用：两池副本与KV双写</h3>\n<p>分离式架构在显存上付出两份代价。第一份是权重副本：prefill池与decode池各持独立副本，且按部署配方两池可以是不同GPU档位、不同并行拓扑，权重不能共享一份显存。第二份是KV的在途与落地：KV从prefill池产出后，在传输窗口内同时存在于源端缓冲与目的端block table，峰值时刻同一请求的KV被计两次。前者是静态占用，后者是动态峰值，二者叠加决定了单机可承载的并发请求数上限。</p>\n<p>把这两项写成容量约束：设单请求KV字节数为S_KV，decode池并发为B_dec，则在途缓冲按流水深度d计算，decode池KV显存需求约为B_dec·S_KV·(1+d/B_dec)量级；prefill池除权重外还需为每个在飞请求保留完整KV直到传输确认，其缓冲需求与prefill批大小成正比。当模型变大、prompt变长，S_KV上升，两池的显存占用同时被推高，而可用并发下降——这是第二个先崩的位置，且它比带宽更隐蔽，因为崩的表现是批大小被迫调小、TPOT抖动，而不是明确的超时。</p>\n<p>具体例子：小规模集群上部署分离式rollout，两池各持一份权重副本，权重占用翻倍，留给KV的显存被压缩，decode池可容纳的并发批次显著小于同池混部方案，资源利用率反而下降——这正是适用边界里“小规模集群不划算”的显存侧成因。工程判断是：只有当单池权重占用相对集群总显存足够小、且rollout的prompt/输出长度分布使两池资源需求差异明显时，分离式才在显存账上划得来。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-37\">三十七 · 通信拓扑与组批的耦合代价</h3>\n<p>两池独立组批是分离式的核心收益，但它把组批决策与通信拓扑绑在了一起。prefill池按chunk组批，批内请求的prompt长度差异决定该批产出的KV总量与分片节奏；decode池按纯decode批次连续自回归，批内请求的已解码长度差异决定每步的计算量。两池的批大小独立设定，意味着prefill池一个大批次可能在瞬间向decode池倾泻大量KV分片，形成带宽脉冲；而decode池的吸收能力受其当前批次的显存余量与block table碎片约束。脉冲与吸收不匹配时，KV在途缓冲膨胀，TTFT尾延迟抬升。</p>\n<p>机制上的解法是让组批感知传输：prefill池的chunk大小不只看算力利用率，还要看“该批KV总量/互联可用带宽”是否超过decode池的在途缓冲水位；decode池的扩容信号除了TPOT，还应包含在途KV字节数的水位。代价是两池调度器之间需要一条低延迟的状态通道交换水位信息，这条通道本身成为新的耦合点——它不能走与KV相同的拥塞链路，否则水位信息本身就被延迟污染。</p>\n<p>具体例子：rollout的请求形态是长prompt、长输出混合。若prefill池按算力最优组了一个含多条长prompt的大批，该批完成后KV总量可达数GB量级，远超decode池瞬时吸收能力，传输窗口内互联被打满，后续短prompt请求的TTFT被连带拖长。把chunk切小、按“KV字节数上限”而非“token数上限”组批，可以削平脉冲，代价是prefill池的算力利用率下降、prefill池需要更多副本才能维持吞吐。这是一笔明确的交换：用prefill算力换TTFT尾延迟。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-38\">三十八 · 功耗与两池档位错配</h3>\n<p>prefill与decode对硬件的需求相反：prefill是算力密集、对显存带宽相对不敏感；decode是显存带宽密集、算力利用率低但每步都要读全量权重与KV。分离式允许两池用不同GPU档位，这既是收益也是功耗账上的风险。若两池档位按各自瓶颈选型，整体功耗接近两池峰值之和；但rollout的负载是波动的，训练侧权重更新会让rollout引擎短暂停摆换权重，此时两池同时进入低利用率状态，功耗下降但吞吐归零，能效比在切换窗口内恶化。</p>\n<p>更细的代价在decode池：纯decode批次的算力利用率天然偏低，GPU大部分时间在等显存带宽，功耗却维持在接近峰值的水平。分离式并不能改善这一点，反而因为decode池要独立承担全部自回归步进而放大了这部分浪费。工程上的做法是把decode池的批大小推到显存容量允许的上限以提高每瓦吞吐，但这又与TPOT约束冲突——批越大，单步延迟越长。功耗在这里不是独立变量，它是批大小决策的下游结果。</p>\n<p>具体例子：两池按不同档位部署后，prefill池在长prompt批次上跑满算力，decode池在长输出阶段持续低算力高带宽运行；当rollout负载从长prompt为主切换到长输出为主，prefill池利用率骤降而decode池成为瓶颈，整体功耗结构随之偏移，容量规划若按峰值功耗预留，会在切换期出现大量闲置功耗预算。这要求容量规划按两池各自的负载分布分别做功耗包络，而不是按集群总算力折算。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-39\">三十九 · 尾延迟：goodput口径下的真实损失</h3>\n<p>分离式的收益必须用SLO口径的goodput衡量，而不是平均吞吐：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}]}{T},\\quad C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>第二个式子给出两池容量配比，它由请求到达率与平均prompt/输出长度决定。问题在于平均值掩盖了尾部：rollout的请求长度分布是长尾的，少数超长prompt请求的KV传输量远超均值，它们要么拖垮自己的TTFT，要么在传输窗口内挤占带宽拖垮同批其他请求的TTFT。goodput的指示函数对这类请求是零贡献，但它们消耗的互联带宽是实打实的。规模上去以后，尾延迟的崩法不是平均TTFT缓慢上升，而是goodput在某个负载点突然塌陷——因为带宽被少数长请求占满，大批本可满足SLO的请求被推出窗口。</p>\n<p>机制上的缓解是给KV传输做优先级与配额：按请求的SLO余量分配带宽，SLO紧的请求优先传输、长prompt请求的分片传输让路；同时prefill池按TTFT目标扩容时，扩容判据应基于“传输项是否已成为瓶颈”而非单纯队列长度。代价是需要per-request的带宽记账，调度器要为每个在飞请求维护已传字节与剩余预算，这套记账在超高并发下本身消耗CPU侧资源。</p>\n<p>具体例子：负载上升时，prefill池队列长度触发扩容，新增副本提升了prefill算力，但互联带宽不变，传输项成为固定瓶颈，新增算力只让KV更快地产出、更快地堆进在途缓冲，TTFT不降反升。这说明分离式架构的扩容必须两池协同：prefill池扩容前先确认互联带宽与decode池吸收能力有余量，否则扩容是无效投入。规模上限受互联带宽与两池副本显存约束，这条边界不是靠加GPU能推开的。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-40\">四十 · 权重切换窗口与版本错配的代价</h3>\n<p>训练侧权重更新要求rollout引擎快速换权重，分离式把这件事变成两池各自推送、按版本号原子切换。切换窗口内，两池不能同时用新旧权重混合服务，否则decode池可能用旧权重继续自回归而prefill池已用新权重产出KV，同一请求的KV与decode权重版本不一致，产出的样本与训练侧策略不一致——这是正确性问题，不是性能问题，代价是整批rollout样本作废。</p>\n<p>机制上，版本号原子切换要求两池在切换点对齐：prefill池停止接收新请求、排空在飞KV传输，decode池在收到版本号后丢弃未完成的旧版本请求或让其跑完再切。这个排空窗口的长度由在飞请求的最大剩余decode步数决定，长输出请求会把窗口拉长到数百毫秒量级，期间两池吞吐下降。若rollout引擎的权重更新频率高，排空窗口占总时间的比例上升，goodput被系统性侵蚀。</p>\n<p>工程判断是：分离式架构下权重切换的成本与请求长度分布直接挂钩，长输出为主的rollout形态会让切换窗口成为不可忽视的吞吐损失项。缓解手段是让切换按池分批进行、以版本号为界做请求路由，新请求只进新版本池、旧请求在旧版本池跑完，两版本短暂共存——代价是切换期显存与算力被两版本分摊，峰值占用上升。这与显存账上的两池副本代价叠加，构成规模上去后第三个先崩的位置：不是带宽也不是显存容量，而是版本共存期的资源峰值。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-41\">四十一 · 跨池传输项：规模上去以后最先崩的是互联带宽，不是算力</h3>\n<p>分离式 rollout 的 TTFT 不再只由 prefill 计算决定，而是被一条加法项钉死：<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>其中 $$S_{\\text{KV}}$$ 是单请求 KV 字节数，随 prompt 长度与模型层数、头数线性增长。长 prompt、大模型时单请求 KV 可达数百 MB，这一项在互联带宽被占满时会直接吞掉 prefill 池省下来的时间。工程判断因此很直接：先算 KV 传输占用的带宽份额，再决定 prefill 与 decode 的池规模比；若传输项已接近 TTFT 预算的一半，扩 prefill 池没有意义，瓶颈在链路上。</p>\n<p>带宽竞争的形态是突发而非平滑。prefill 池按 chunk 组批，一批请求几乎同时产出完整 KV 并按层分片写入 decode 池的 block table，瞬时占用接近链路峰值；decode 池侧则持续以纯 decode 批次自回归，对互联的依赖是低频小块。传输与计算流水重叠能把这段延迟藏进下一个 chunk 的 prefill 计算里，但重叠的前提是链路有余量——一旦 rollout 的 prompt 长度分布右移，余量消失，隐藏失效，TTFT 尾延迟先于均值恶化。尾延迟比均值更早暴露问题，因为 SLO 是按分位数而非平均口径结算的。</p>\n<p>第二处先崩的是权重版本一致性。训练侧新权重经同步通道分别推送到两池并按版本号原子切换，两池各自独立调度意味着切换存在时间窗：decode 池若仍用旧版本继续自回归，产出的样本与训练侧策略不一致，rollout 数据的有效性被静默污染，且这种错误不体现在延迟指标上。原子切换必须把“停止接纳新批次、排空在飞请求、切换、恢复”做成两池协同的状态机，而不是各自本地生效。</p>\n<p>规模下限同样由副本结构决定。两池各持独立副本与调度器，显存总占用上升，小规模集群下副本开销摊不薄，利用率反而低于混部；适用边界是大规模集群且阶段资源需求差异明显。可用一张代价对照表定位失效顺序：</p>\n<table class=\"mini\"><thead><tr><th>规模上升时</th><th>先触发的约束</th><th>观测信号</th></tr></thead><tbody><tr><td>prompt 变长</td><td>互联带宽与 TTFT 传输项</td><td>TTFT 尾部分位数超 SLO</td></tr><tr><td>池规模扩大</td><td>两池副本显存与调度开销</td><td>单卡有效吞吐下降</td></tr><tr><td>权重高频更新</td><td>版本切换窗口</td><td>样本与训练策略偏差</td></tr></tbody></table>\n<p>功耗侧的表现是两池档位不同、峰值错开：prefill 池在 chunk 组批时接近算力峰值，decode 池长期处于带宽受限的低算力占用状态，整机功率预算需按两池各自的峰值而非平均值配置，否则 prefill 池扩容会撞到机架功率上限。</p>\n<h3 id=\"alg-pd-disagg-rollout-sec-42\">四十二 · 精度漂移：版本错配与数值路径分叉</h3>\n<p>分离式 rollout 的精度问题几乎不来自单卡数值本身，而来自“两条路径”之间的不一致。prefill 池与 decode 池各持一份权重副本，权重同步通道按版本号原子切换——但“原子”只在单池内部成立。若 prefill 池已切到 v+1、decode 池仍在 v，则一个请求的首 token 与完整 KV 由 v+1 算出，后续自回归却由 v 续写，样本在语义上被拼接成两个模型的产物。这类样本进入训练后表现为 loss 曲线出现与批次强相关的锯齿，而非平滑下降。诊断手段是把版本号打进每个 token 的元数据，在 decode 池出口做一次“首 token 版本 vs 续写版本”的一致性断言，任何跨版本拼接直接丢弃并计数。</p>\n<p>第二条精度路径是 KV 跨池传输的数值通路。KV 按层分片经 NVLink/CXL/IB 写入 decode 池的 block table，若两侧对 KV 的 dtype 约定不同（一侧以 BF16 计算并落盘、另一侧按 FP8 读取），误差不会在单请求上爆发，而会在长输出上累积成尾部漂移。工程做法是在 block table 条目上携带 dtype 与量化 scale 指纹，decode 池加载时校验指纹，不匹配则拒绝该 block 并回退到重算。代价是每次跨池传输多一个元数据字段与一次校验，延迟增量可忽略，但显存里需要为指纹留出与 block 数成正比的旁路表。</p>\n<p>第三条是采样路径分叉：批不变采样要求同一请求在不同批组成下产出相同分布，而两池独立组批意味着 prefill 池的批与 decode 池的批毫无关系。若采样器状态（随机种子、温度调度步数）在跨池交接时未随请求迁移，decode 池会用本地默认种子重启采样流，导致同一 prompt 在重放时不可复现。诊断靠“重放一致性”探针：固定种子重放同一批请求，比对输出哈希；不一致即定位到交接点。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-43\">四十三 · OOM：两池副本与 KV 峰值叠加</h3>\n<p>分离式部署把显存总占用推高的机制很直接：两池各持独立权重副本，且 prefill 池在完成全 prompt 前向的瞬间持有该请求的完整 KV，decode 池则持有活跃序列的全部 KV 直至 EOS。峰值出现在“prefill 池刚写完、decode 池尚未释放旧序列”的重叠窗口。设单请求 KV 字节数为 <span class=\"formula\">$$S_{\\text{KV}}$$</span>，则 decode 池的 KV 占用近似为活跃序列数乘以 <span class=\"formula\">$$S_{\\text{KV}}$$</span>，而 prefill 池的瞬时占用由 chunk 批内 prompt 总长决定；两者相加才是真实峰值，任何按单池估算容量的做法都会在长 prompt 混合负载下撞墙。</p>\n<p>OOM 的典型症状不是进程崩溃，而是调度器开始“静默降批”：decode 池为腾出 block 而缩短连续批，TPOT 随之抬升并越过 SLO，goodput 下降却没有任何错误日志。监控必须把“因显存压力被拒绝入批的请求数”作为一等指标，与 block table 的空闲块数、KV 传输队列深度一起看。回滚策略上，优先降的是 prefill 池的 chunk 批上限而非 decode 池的并发——因为 prefill 池的瞬时峰值更陡，且降它只影响 TTFT，不影响已在 decode 池中的序列。</p>\n<p>具体例子：长 prompt、长输出混合负载下，单请求 KV 可达数百 MB；若 decode 池按“活跃序列数 × 数百 MB”预留，再叠加 prefill 池的 chunk 峰值，两池副本显存总占用翻倍在小规模集群上直接表现为可用并发腰斩，资源利用率反而下降——这正是适用边界里“小规模不划算”的显存侧成因。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-44\">四十四 · 批抖动与路由不均：两个不同源的尾延迟</h3>\n<p>批抖动来自两池组批节奏的解耦。prefill 池按 TTFT 目标扩容、以 chunk 组批，其批组成随 prompt 长度分布剧烈变化；decode 池以纯 decode 批次连续自回归，批一旦成形就稳定运行到 EOS。当 prefill 池因长 prompt 积压而放慢吐出首 token 的节奏，decode 池会周期性出现“批内序列陆续结束、新序列尚未到达”的空窗，随后又因一批首 token 同时抵达而形成尖峰。这种抖动在 TPOT 曲线上表现为方波而非噪声，诊断时应对 TPOT 做分窗口统计，观察其周期性而非均值。</p>\n<p>路由不均则是另一个源：请求进入 prefill 池后按 chunk 分派到各 GPU，若分派只看队列长度而不看 prompt 长度分布，短 prompt 会挤在少数 GPU 上快速周转、长 prompt 堆在另一些 GPU 上拖长 chunk，造成池内负载倾斜。倾斜不会立刻违反 SLO，但会让扩容决策失真——按平均利用率扩容时，热点 GPU 已过载而冷点仍空闲。工程上把“每 GPU 的 chunk 占用时长方差”作为路由健康度指标，方差超阈值即触发重分派或按长度分桶路由。</p>\n<p>尾延迟尖刺的复合形态是：KV 传输与计算流水重叠本用于隐藏搬运延迟，但当互联带宽被长 prompt 的数百 MB 传输占满时，重叠失效，<span class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</span> 中的传输项从被隐藏变为主导，TTFT 尖刺与带宽利用率曲线同步抬升。诊断的关键是把 TTFT 分解为 prefill 计算项与传输项分别打点，而不是只看端到端；只有分解后才能判断是该扩 prefill 池算力还是该限流 KV 传输。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-45\">四十五 · 监控口径：以 SLO 为唯一裁决</h3>\n<p>分离式 rollout 的监控不能沿用单池的吞吐口径，因为两池的瓶颈不同、扩容信号不同。裁决标准应是 goodput：<span class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}]}{T}$$</span>。这个口径同时惩罚“快但违约”和“慢但合规”，避免用平均延迟掩盖尾部分布。落地时按请求维度记录 TTFT 与 TPOT 的达标位，聚合到分钟窗口，任何一池的扩容决策都以 goodput 的边际变化为依据，而非以 GPU 利用率为依据。</p>\n<p>需要同时盯住的四组指标：其一，KV 传输队列深度与互联带宽占用率，用于预判 TTFT 尖刺；其二，两池权重版本号与切换耗时，用于捕捉版本错配窗口；其三，decode 池空闲块数与因显存拒绝入批计数，用于预判 OOM 引发的静默降批；其四，prefill 池每 GPU chunk 占用时长方差，用于识别路由倾斜。四组指标各自对应一类失败模式，不做加权合成——合成会掩盖单点故障。</p>\n<p>资源配比的健康度用 <span class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</span> 跟踪：该比值随 rollout 的 prompt/输出长度分布漂移，若实际配比长期偏离公式预测值，说明扩容信号被某一池的局部瓶颈劫持，需回查路由与批组成。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-46\">四十六 · 回滚：分级动作与原子边界</h3>\n<p>回滚的第一原则是“不跨池回滚”。两池独立副本与调度器意味着回滚动作必须按池分别执行，且以版本号为原子边界：先将 decode 池冻结在旧版本、停止接收新请求，待其活跃序列排空后再切版本，最后才让 prefill 池跟进。反向顺序会造成新 prefill 产出的 KV 被旧 decode 消费，正是精度漂移的成因。冻结窗口的代价是 decode 池吞吐短时归零，因此回滚应尽量在批边界触发，把窗口压到单个批周期内。</p>\n<p>分级动作按失败模式对应：精度类问题（版本错配、dtype 指纹不匹配）走“拒绝 block + 重算”的局部回滚，不动全局版本；OOM 类走“降 prefill chunk 上限 + 释放非活跃 block”的容量回滚；批抖动与尾延迟尖刺走“限流 KV 传输 + 按长度分桶路由”的调度回滚；路由不均走“重分派 + 方差阈值收紧”。四类动作的作用域不同，混用会让诊断信号互相污染。</p>\n<p>最后一条工程判断落在权重同步通道本身：原子切换的正确性依赖“版本号在传输前确定、在写入后校验”，而不是依赖两池的时钟同步。把版本号作为 KV block 与 token 元数据的必填字段，让不一致在消费侧暴露而非在训练侧表现为不可解释的 loss 抖动，是这套架构里成本最低、收益最直接的可观测性投入——它把一类沉默的精度故障转成一条可计数的拒绝记录。</p>\n\n\n<h3 id=\"alg-pd-disagg-rollout-sec-47\">四十七 · 失效边界：跨池带宽、版本错配与副本开销</h3>\n<p>分离式 rollout 的稳定性问题几乎都落在两个池的“接缝”上，而不是单池内部。最直接的一条是 KV 搬运把互联带宽吃满：<span class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</span> 中的传输项不参与任何计算隐藏，当请求形态是长 prompt、模型又大时，单请求 KV 可达数百 MB，prefill 池的产出速率一旦超过互联可持续带宽，decode 池的 block table 写入就会排队，TTFT 直接顶穿 SLO。此时监控上表现为 prefill 池 SM 利用率并不高、但 TTFT 分位数持续抬升，而 decode 池出现“空转等 KV”的低占用窗口——这是带宽瓶颈而非算力瓶颈的典型指纹，扩容 prefill 池无效，只会把更多 KV 压进同一条管道。诊断应把 KV 传输字节数、互联端口吞吐与 TTFT 分解（prefill 计算项 vs 传输项）作为一组联动指标采集，按层分片的传输与计算流水重叠是否真的生效，要看传输项是否被压在 prefill 计算时间之下。</p>\n<p>第二条是权重版本错配。训练侧新权重经同步通道分别推送两池并按版本号原子切换，但“分别推送”意味着两池的切换不是同一个原子事件：若 decode 池先切、prefill 池后切，或某一池的推送因队列积压延迟，就会出现同一批 rollout 样本由不同版本权重前后拼接产出。这类样本在 RL 训练里是隐性毒化——它不会报错，只会让重要性采样比失真、梯度方向偏移。工程上必须把版本号写进每个请求的元数据并随 KV 一起跨池传递，decode 池拒绝消费版本号低于自身当前版本的 KV，两池切换以同一版本栅栏为准；监控上以“跨池请求版本不一致计数”作为一等指标，非零即告警并触发回滚到上一稳定版本。回滚本身也要原子：保留上一版本权重常驻或可快速重载，避免回滚窗口内两池再次错位。</p>\n<p>第三条是批抖动与路由不均。两池各自维护队列与 SLO，prefill 池按 TTFT 目标扩容、decode 池按 TPOT 目标扩容，独立扩缩容在负载配方突变时会互相踩踏：prompt/输出长度分布偏移使 <span class=\"formula\">$$C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</span> 偏离既定配比，一侧扩容滞后就表现为另一侧的批大小抖动——decode 池纯 decode 批次被新到的 KV 流反复打断重组，TPOT 出现尖刺；prefill 池 chunk 组批因上游路由不均而长短批混排，TTFT 方差放大。尾延迟尖刺往往不是均值问题，而是路由把长 prompt 集中打到少数 prefill 实例上。诊断要看分实例的队列深度、批大小时间序列与 P99 分解，而不是池级均值。</p>\n<p>最后是规模边界带来的资源代价。两池各持独立副本与调度器，显存总占用上升，小规模集群下副本开销使利用率反而下降，规模上限同时受互联带宽与两池副本显存约束。判断是否值得分离，应比较分离后的 goodput 增益与副本显存、互联占用带来的机会成本：当集群规模不足以让两池都跑到各自的经济批大小，或互联带宽无法把传输项压到 SLO 预算之内时，退回同池混部（参见分块预填背驮解码的拼批互补思路）比强行分离更稳。监控体系应把“传输项占 TTFT 预算比例”“版本不一致计数”“分实例批大小方差”三项设为回滚触发器，任一越界即降级到同池模式，而不是等到尾延迟全面劣化再被动处置。</p>\n<h3 id=\"alg-pd-disagg-rollout-sec-48\">四十八 · 同族算法的三条分界线</h3>\n<p>把分离式预填解码 Rollout 放回同族里看，真正决定选型的不是“谁更快”，而是三条结构性分界线：<strong>阶段是否拆池</strong>、<strong>KV 是否成为一级调度对象</strong>、<strong>瓶颈互补发生在批内还是池间</strong>。分块预填背驮解码把 prefill 的算力密集块塞进 decode 批的空隙里，互补发生在同一个 GPU 的同一个批次内，代价是 decode 的 TPOT 被 chunk 边界扰动；KV 中心分离式池化把 KV 当作全局可路由的资源做跨请求复用，收益来自前缀命中率而非阶段隔离；本算法则把两阶段推到不同 GPU 池，互补发生在集群层面，代价是互联带宽与两套副本。这三条线决定了后面所有决策表的行。</p>\n<p>选型时先问一句：rollout 的瓶颈是<strong>阶段间干扰</strong>还是<strong>阶段内效率</strong>。若混部时 prefill 的长 prompt 前向把 decode 的连续自回归打断、TPOT 抖动超出 SLO，那是干扰问题，拆池直接对症；若单池内 decode 批的显存带宽利用率本就上不去、KV 复用率低，那是效率问题，背驮或池化更合适。用 SLO 口径的 goodput 做判据：</p>\n<div class=\"formula\">$$\\text{Goodput} = \\frac{\\sum_i \\mathbb{1}[\\text{TTFT}_i\\le S_{\\text{ttft}}\\wedge \\text{TPOT}_i\\le S_{\\text{tpot}}]}{T},\\quad C_{\\text{pre}}/C_{\\text{dec}} = \\frac{\\rho_{\\text{pre}}\\cdot \\bar{L}_{\\text{prompt}}}{\\rho_{\\text{dec}}\\cdot \\bar{L}_{\\text{out}}}$$</div>\n<p>第二个式子给出容量配比的先验：当 rollout 的 prompt 长度均值远大于输出长度均值时，prefill 侧的算力占比被抬高，两池的 GPU 数量比必须跟着走，否则 decode 池空转、prefill 池排队。混部无法做这件事，因为一张卡同时承担两种相反的资源画像——prefill 吃满 tensor core 算力，decode 吃满 HBM 带宽与 KV 容量。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-49\">四十九 · 决策表：五种形态的适用条件</h3>\n<p>下表按“拆池/不拆池”“KV 是否跨池”“规模门槛”三个维度给出选择，行是可选的同族形态，列是判据。表中不写绝对数字，只写方向性条件，因为阈值取决于模型层数、隐藏维与互联代际。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>阶段拆池</th><th>KV 流向</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>本算法（分离式预填解码）</td><td>是，两池独立扩缩容</td><td>prefill→decode 跨池写入 block table</td><td>大规模集群；prompt/输出长度分布偏斜明显；TTFT 与 TPOT 需分别约束；训练侧频繁换权重</td><td>互联带宽占用、两套副本显存、部署复杂度</td></tr>\n<tr><td>分块预填背驮解码</td><td>否，同池拼批</td><td>不出卡</td><td>中等规模；decode 批有空隙可填；能容忍 chunk 边界带来的 TPOT 抖动</td><td>decode 批被 chunk 拉长，尾延迟变差</td></tr>\n<tr><td>KV 中心分离式池化</td><td>部分，池化层独立</td><td>池内路由与复用</td><td>前缀重复率高、多轮对话或共享系统提示；KV 命中率是主要收益来源</td><td>池化层带宽与索引开销，命中率低时反噬</td></tr>\n<tr><td>分页 KV 批量 Rollout</td><td>否</td><td>卡内分页</td><td>变长输出、显存碎片严重；单池即可满足 SLO</td><td>页表管理与碎片整理开销</td></tr>\n<tr><td>异步 Rollout 流水线</td><td>否，时间维度错峰</td><td>不出卡</td><td>训练与 rollout 交替、阶段性能容忍陈旧权重</td><td>样本陈旧度上升，需版本对齐</td></tr>\n</tbody></table>\n<p>读表方式：先看第一列。若集群规模不足以让两池都跑到有意义的批大小，拆池会让每池的批被稀释，显存总占用翻倍而利用率下降——这是本算法在小规模下的典型反噬。若前缀命中率是主要矛盾，池化优先；若只是变长输出导致显存碎片，分页 KV 足够，不必引入跨池传输。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-50\">五十 · 用 TTFT 分解式做定量筛选</h3>\n<p>拆池的收益必须覆盖传输项，否则不如背驮。判据是把 TTFT 拆成两段：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>其中 $$S_{\\text{KV}}$$ 是单请求 KV 字节数，随层数、KV 头数、头维与 prompt 长度线性增长；$$BW_{\\text{interconnect}}$$ 是跨池有效带宽。长 prompt、大模型时传输量可达数百 MB/请求，此时传输项不再是噪声。工程判断的做法是：先测出混部下的 TTFT 抖动幅度，再估算拆池后传输项占 TTFT 的比例。若传输项占比小到可被“传输与计算流水重叠”隐藏，拆池净收益为正；若传输项与 prefill 计算同量级，则拆池只是把排队延迟换成了搬运延迟，SLO 未必改善。</p>\n<p>举例：一个长 prompt 请求在混部池里因 decode 批占卡而排队，TTFT 超出 SLO；拆池后 prefill 池按 TTFT 目标独立扩容，排队消失，但 KV 需按层分片经 NVLink/CXL/IB 写入 decode 池。若互联带宽被同时进行的多条传输占满，TTFT 反而由传输项主导——这正是失败模式“KV 跨池传输占满互联带宽，长 prompt 场景 TTFT 超出 SLO”的成因。因此定量筛选的第二问是：互联是否有余量承载峰值并发下的 KV 流量，而不只是平均流量。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-51\">五十一 · 权重同步与版本一致性作为选型硬约束</h3>\n<p>RL rollout 与普通推理服务的关键差异在于训练侧持续产出新权重，rollout 引擎必须快速换权重。混部时一次换权重冻结整卡，prefill 与 decode 同时停摆；拆池后两池各持独立副本，新权重经权重同步通道分别推送并按版本号原子切换，单池切换期间另一池继续服务，这是本算法在训练-推理解耦上的实质收益。选型时要把这条当硬约束而非加分项：若训练步频高到权重切换成为主要停顿来源，拆池几乎是唯一解；若权重更新稀疏，异步流水线或背驮更省。</p>\n<p>代价随之而来：两池版本必须严格对齐，否则 decode 池用旧权重产出的样本与训练侧策略不一致，污染优势估计。失败模式“两池权重版本切换不同步”不是偶发故障，而是拆池架构的固有风险面，需要版本号在请求级携带、decode 侧拒收跨版本 KV 或按版本分队列。工程上这意味着调度器要维护版本维度的队列，复杂度高于单池。对照之下，背驮与分页 KV 都在单池内，版本切换是原子的，没有错配窗口——这是它们在中规模场景仍具吸引力的隐性理由。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-52\">五十二 · 规模门槛与显存账</h3>\n<p>拆池要求两池各自持有完整模型副本（或至少各自的分片），显存总占用上升。小规模集群下，两池独立副本使显存总占用翻倍，资源利用率反而下降，这是适用边界里写明的反噬。判断门槛的粗算：设单池在目标批大小下需要的显存为 M，拆池后总需求约 2M 减去因批减小而释放的部分；只有当集群 GPU 数足以让两池都达到有意义的批大小、且互联带宽足以承载 KV 峰值流量时，拆池的 goodput 才占优。</p>\n<p>另一条账是并行拓扑：两池可取不同 GPU 档位与不同并行切分，prefill 池偏重算力与 chunk 组批，decode 池偏重 KV 容量与带宽。这种非对称配置是拆池的独特自由度，混部与背驮都做不到。选型时若 rollout 的 prompt/输出长度分布随训练阶段漂移，非对称配置可按阶段重调 $$C_{\\text{pre}}/C_{\\text{dec}}$$，这是长期运行下的主要收益来源，而非单次请求的延迟改善。</p>\n<p>最终落在一条工程判断上：先测混部下的 TTFT 抖动与 TPOT 抖动是否同源，若同源则背驮或分页 KV 即可；若异源且规模与互联余量都过门槛，拆池并把版本号写进请求元数据、把 KV 传输与计算流水重叠作为默认路径，而不是可选优化。</p>\n\n<h3 id=\"alg-pd-disagg-rollout-sec-53\">五十三 · 分池边界：什么规模的 rollout 才值得拆</h3>\n<p>本方案与同族算法的分水岭不在“是否分离”，而在“分离的粒度”。分块预填背驮解码仍在同一池内拼批，用预填块填充解码批的空洞，把算力密集与带宽密集两类工作压进同一个 kernel 序列，代价是调度器要维护混合批的 token 预算，收益是零跨池流量；KV 中心分离式池化把 KV 当作一级调度对象，跨请求做前缀复用与全局置换，优化目标是缓存命中率而非阶段隔离；本方案则按阶段物理拆池，prefill 池只跑全 prompt 前向，decode 池只跑自回归，两池各自扩缩容、各自组批、各自持权重副本。判断依据是阶段资源需求比 $C_{\\text{pre}}/C_{\\text{dec}}$ 的偏离程度：当 rollout 的 prompt 长度分布与输出长度分布使该比值远离 1，混部必然让一侧成为另一侧的干扰源，拆池的收益才开始覆盖跨池传输与双副本的固定成本。反过来，若请求形态接近“短 prompt、短输出”，两池负载曲线几乎重合，拆池只是把一份调度器复制成两份，显存与部署复杂度上升而 goodput 不动。</p>\n<p>跨池传输项是硬约束，直接写进 TTFT：</p>\n<div class=\"formula\">$$T_{\\text{TTFT}} = T_{\\text{prefill}} + \\frac{S_{\\text{KV}}}{BW_{\\text{interconnect}}}$$</div>\n<p>其中 $S_{\\text{KV}}$ 为单请求 KV 字节数，随层数、头数、头维度与 prompt 长度线性增长，长 prompt、大模型时可达数百 MB/请求。工程上必须让 KV 按层分片经 NVLink/CXL/IB 写入 decode 池对应 block table，并与 prefill 计算流水重叠——第 $l$ 层 KV 写完即可启动第 $l+1$ 层计算，把搬运延迟藏在后续层的 tensor core 占用之后；否则传输项会直接叠加在 TTFT 上，长 prompt 场景下轻易击穿 SLO。这也解释了规模上限：互联带宽是分母，两池副本显存是另一条天花板，集群越小，这两条约束越早生效。</p>\n<p>失效条件有三类，工程上要逐条设防。其一是带宽饱和：当 prefill 池扩容速度快于互联扩容，KV 搬运占满链路，TTFT 超出 SLO，此时扩容 prefill 反而恶化端到端指标，正确动作是限流而非加卡。其二是权重版本错配：训练侧新权重经权重同步通道分别推送两池，必须按版本号原子切换，若 decode 池仍用旧权重自回归，产出的样本与训练侧策略不一致，rollout 数据 silently 污染，这类故障不体现在延迟指标上，只能靠版本号断言拦截。其三是小规模集群的资源倒挂：两池各持独立副本与调度器，显存总占用上升，若集群规模不足以让两池都跑到高利用率，拆池后的有效吞吐低于混部。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选分块预填背驮解码</th><th>选 KV 中心池化</th><th>选本方案（按阶段拆池）</th></tr></thead><tbody><tr><td>阶段需求比 $C_{\\text{pre}}/C_{\\text{dec}}$</td><td>接近 1，混部干扰可被拼批吸收</td><td>不敏感，按缓存命中调度</td><td>显著偏离 1，需独立扩缩容</td></tr><tr><td>prompt 长度</td><td>中等，块切分开销可控</td><td>长且前缀重复率高</td><td>长 prompt、长输出混合</td></tr><tr><td>互联预算</td><td>无跨池流量</td><td>池内搬运为主</td><td>需 NVLink/CXL/IB 余量承载数百 MB/请求</td></tr><tr><td>集群规模</td><td>中小集群友好</td><td>中大集群，缓存复用摊薄成本</td><td>大规模集群，双副本显存可摊薄</td></tr><tr><td>权重切换</td><td>单池切换，版本一致易保证</td><td>单池切换</td><td>两池原子切换，需版本号通道</td></tr></tbody></table>\n<p>决策顺序建议按代价从低到高排：先测混部下的 TTFT 与 TPOT 尾部，若尾部由另一阶段的批抢占造成，再评估拆池；拆池前先算 $S_{\\text{KV}}/BW_{\\text{interconnect}}$ 是否落在 TTFT 预算的可接受比例内，并确认两池能各自跑到目标利用率。若前缀复用率高，KV 中心池化在同等互联预算下往往先拿到收益；只有当阶段资源配比需要按 prompt/输出长度分布独立调优、且训练-推理解耦要求权重快速切换时，按阶段拆池才是正确解。SLO 口径下的收益应以 goodput 计量，即同时满足 TTFT 与 TPOT 约束的请求占比，而非单看某一阶段的吞吐。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2024 · 奖励模型与验证器推理</td></tr><tr><td>解决什么</td><td>RL rollout的prefill与decode对算力/带宽需求相反，混部时互相干扰，且训练侧权重更新要求rollo…</td></tr><tr><td>一句话机制</td><td>将prefill与decode拆到不同GPU池，KV经高带宽互联从prefill池传到decode池，两池按各自瓶颈独…</td></tr><tr><td>代价与失效</td><td>KV跨池传输占用互联带宽并增加TTFT，长prompt、大模型时传输量可达数百MB/请求；两池需独立副本与调度器，部署复杂度与显存总占用上…</td></tr><tr><td>后继</td><td>在线Rollout剪枝</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-pd-disagg-rollout · 共 8 个片段</p>\n";break;}}})();
